args.command:
node -e '
// Test exact ramp curve & physics trajectory in memory
const DEG = Math.PI / 180;
function buildRamp(numSamples = 600) {
  // We want total angle = 115 deg, Y_end = 20.0 m
  // Let s in [0, L]. Use smooth curvature profile kappa(s)
  const targetAngle = 115 * DEG;
  // Unscaled profile u in [0, 1]:
  // 0..0.10: flat lead-in (0 curvature)
  // 0.10..0.32: smooth sine-squared ramp up of curvature
  // 0.32..0.92: main curvature (slightly increasing toward hook)
  // 0.92..1.00: hold curvature to 115 deg
  function rawWeight(u) {
    if (u < 0.08) return 0;
    if (u < 0.30) {
      const t = (u - 0.08) / 0.22;
      return 0.5 - 0.5 * Math.cos(Math.PI * t);
    }
    return 1.0 + 0.25 * ((u - 0.30) / 0.70);
  }
  let integralW = 0;
  const N = 2000;
  for (let i = 0; i < N; i++) {
    integralW += rawWeight((i + 0.5) / N) / N;
  }
  const kScale = targetAngle / integralW; // so integral of kappa(u) du = targetAngle
  // Now integrate with L = 1 to find Y(1), then scale L so Y(L) = 20.0
  let x = 0, y = 0, theta = 0;
  for (let i = 0; i < N; i++) {
    const u = (i + 0.5) / N;
    const du = 1 / N;
    const k = kScale * rawWeight(u);
    theta += k * du;
    x += Math.cos(theta) * du;
    y += Math.sin(theta) * du;
  }
  const L = 20.0 / y;
  console.log("Computed L:", L.toFixed(3), "End X:", (x * L).toFixed(3), "End Y:", (y * L).toFixed(3), "End deg:", (theta / DEG).toFixed(2));
}
buildRamp();
'

