node -e '
const DEG = Math.PI / 180;
function buildRamp() {
  const targetAngle = 115 * DEG;
  function rawWeight(u) {
    if (u < 0.06) return 0;
    if (u < 0.22) {
      const t = (u - 0.06) / 0.16;
      return (0.5 - 0.5 * Math.cos(Math.PI * t)) * 1.35;
    }
    if (u < 0.68) return 1.35;
    // slightly tighter or gentler at top: gentler curvature between 85 and 115 deg gives longer arc at >90 deg -> bigger hook!
    const t = (u - 0.68) / 0.32;
    return 1.35 * (1 - 0.52 * t);
  }
  const N = 2000;
  let integralW = 0;
  for (let i = 0; i < N; i++) integralW += rawWeight((i + 0.5) / N) / N;
  const kScale = targetAngle / integralW;
  let x = 0, y = 0, theta = 0, maxX = 0, yAt90 = 0;
  for (let i = 0; i < N; i++) {
    const u = (i + 0.5) / N;
    const du = 1 / N;
    const k = kScale * rawWeight(u);
    const prevTheta = theta;
    theta += k * du;
    x += Math.cos(theta) * du;
    y += Math.sin(theta) * du;
    if (x > maxX) maxX = x;
    if (prevTheta < 90 * DEG && theta >= 90 * DEG) yAt90 = y;
  }
  const L = 20.0 / y;
  console.log({
    L: (L).toFixed(2),
    endX: (x * L).toFixed(2),
    maxX: (maxX * L).toFixed(2),
    overhang: ((maxX - x) * L).toFixed(2),
    yAt90: (yAt90 * L).toFixed(2),
    endY: (y * L).toFixed(2),
    endDeg: (theta / DEG).toFixed(2)
  });
}
buildRamp();
'

