    { id: "ROLL_POS_L", lx: 0.0, ly: +0.28, lz: -0.92, fx: 0, fy: -0.85, fz: +0.52, maxShare: 0.16, thrust: 0 },
    { id: "ROLL_POS_R", lx: 0.0, ly: -0.28, lz: +0.92, fx: 0, fy: +0.85, fz: -0.52, maxShare: 0.16, thrust: 0 },
    { id: "ROLL_NEG_L", lx: 0.0, ly: -0.28, lz: -0.92, fx: 0, fy: +0.85, fz: +0.52, maxShare: 0.16, thrust: 0 },
    { id: "ROLL_NEG_R", lx: 0.0, ly: +0.28, lz: +0.92, fx: 0, fy: -0.85, fz: -0.52, maxShare: 0.16, thrust: 0 },
    { id: "REAR_L", lx: -2.20, ly: -0.10, lz: -0.36, fx: 1, fy: 0.12, fz: 0, maxShare: 0.18, thrust: 0 },
    { id: "REAR_R", lx: -2.20, ly: -0.10, lz: +0.36, fx: 1, fy: 0.12, fz: 0, maxShare: 0.18, thrust: 0 }
  ];

  let phase = "WAIT_START";
  let phaseTime = 0;
  let maxSReached = -12;
  let maxPitchDeg = 0;
  let maxImpactImpulse = 0;
  let crashed = false;
  let landedCleanly = false;
  const dt = 1 / 240;

  for (let step = 0; step < 240 * 15; step++) {
    const t = step * dt;
    phaseTime += dt;

    // Basis vectors of car in world frame
    const fwd = new Vec3(1, 0, 0).applyQuaternion(quat);
    const up = new Vec3(0, 1, 0).applyQuaternion(quat);
    const right = new Vec3(0, 0, 1).applyQuaternion(quat);
    const qInv = quat.clone().invert();

    // Closest surface to car center
    const surf = querySurface(pos.x, pos.y, pos.z);
    const sPos = surf ? surf.s : pos.x;
    if (sPos > maxSReached) maxSReached = sPos;

    // Compute pitch angle along ramp (0 deg = +X, 90 deg = +Y, 115 deg = hook)
    const rampPitchDeg = Math.atan2(fwd.y, fwd.x) * RAD;
    if (rampPitchDeg > maxPitchDeg) maxPitchDeg = rampPitchDeg;

    // Flight & Stunt State Machine
    let driveForceCmd = 0;
    let brakeCmd = 0;
    let fanCmd = 0;
    for (const n of nozzles) n.thrust = 0;

    const fwdSpeed = vel.dot(fwd);
    const wheelsInContact = wheels.filter(w => w.contact).length;

    if (phase === "WAIT_START") {
      brakeCmd = 1.0;
      if (t >= 0.65) {
        phase = "CLIMB";
        phaseTime = 0;
      }
    } else if (phase === "CLIMB") {
      fanCmd = sPos > -1.0 ? 1.0 : 0.4;
      const targetS = 29.75; // near lip (L=31.65, so front bumper is right at the lip, pitch ~112 deg)
      const remS = targetS - sPos;
      // Target speed profile: accelerate to entrySpeed, then smoothly decelerate into targetS
      // Wait: if entrySpeed is set low by user ("Too slow"), cap target speed to entrySpeed!
      const stopBrakeProfile = Math.sqrt(Math.max(0, 2 * 13.5 * Math.max(0, remS)));
      const targetV = Math.min(entrySpeed, stopBrakeProfile);

      if (remS <= 0.25 && Math.abs(fwdSpeed) < 1.2 && sPos > 27.0) {
        phase = "HANG";
        phaseTime = 0;
      } else if (wheelsInContact === 0 && pos.y > 3.0 && vel.y < -2.0) {
        // Fell off the ramp!
        phase = "FALL_ABORT";
        phaseTime = 0;
      } else if (sPos > 6.0 && fwdSpeed < -2.5) {
        // Sliding backward down the ramp!
        phase = "SLIDE_BACK";
        phaseTime = 0;
      } else {
        const vErr = targetV - fwdSpeed;
        if (sPos < 4.0) {
          // Accelerate up to entrySpeed on approach
          driveForceCmd = Math.max(0, Math.min(1, vErr * 0.45)) * mass * (entrySpeed * 0.92);
          // Rear cold-gas boost on launch if entrySpeed is high
          if (vErr > 2.0 && entrySpeed >= 20) {
            const rearBoost = Math.min(1, vErr * 0.15) * totalThrusterForce * 0.16;
            nozzles[8].thrust = rearBoost;
            nozzles[9].thrust = rearBoost;
          }
        } else {
          // On the curve: drive/brake through tires only!
          // Note: max tire force is strictly bounded by mu * NormalLoad in the wheel solver!
          if (vErr >= 0) {
            driveForceCmd = Math.min(mass * 18.0, vErr * mass * 4.5);
          } else {
            brakeCmd = Math.min(1.0, -vErr * 0.35);
          }
        }
      }
    } else if (phase === "HANG") {
      fanCmd = 1.0;
      brakeCmd = 1.0;
      // Hold position on lip with tire friction; if tires slip, car slides
      if (wheelsInContact === 0 && vel.y < -2.0) {
        phase = "FALL_ABORT";
        phaseTime = 0;
      } else if (phaseTime >= 2.05) {
        phase = "RELEASE_PITCH";
        phaseTime = 0;
      }
    } else if (phase === "RELEASE_PITCH") {
      // Cut fans so car detaches from the 112 deg lip!
      fanCmd = 0.0;
      brakeCmd = 0.0;
      // Pitch nose from 112 deg to 180 deg (horizontal belly-up facing -X) and push clear of lip
      // In body frame, pitching from 112 deg toward 180 deg is +omega.z (nose UP in body frame!)
      // Wait: let us check! At theta = 112 deg, fwd = (cos 112, sin 112, 0), up = (-sin 112, cos 112, 0).
      // Increasing theta from 112 deg to 180 deg is a +Z rotation in world frame, which is +omega.z in body frame!
      // Firing FL_DOWN and FR_DOWN applies +Y force at lx = +1.35 -> torque tau_z = lx * Fy > 0 (+omega.z)!
      // Plus it pushes the car along +up = (-sin 112, cos 112, 0), which pushes it LEFT (-X) away from the ramp wall!
      const thetaCurr = Math.atan2(fwd.y, -fwd.x); // 0 when fwd is (-1, 0, 0)!
      // Wait: when theta=112 deg, fwd.x = -0.37, fwd.y = +0.93 -> atan2(fwd.y, -fwd.x) = 68 deg.
      // As it pitches to (-1, 0, 0), atan2(fwd.y, -fwd.x) goes from 68 deg to 0 deg!
      const pitchToLevel = Math.atan2(fwd.y, -fwd.x);
      const pitchRate = omega.z;
      const pitchCmd = Math.max(-1, Math.min(1, pitchToLevel * 2.8 - pitchRate * 0.45));
      if (pitchCmd > 0) {
        nozzles[0].thrust = pitchCmd * totalThrusterForce * 0.22;
        nozzles[1].thrust = pitchCmd * totalThrusterForce * 0.22;
      } else {
        nozzles[2].thrust = -pitchCmd * totalThrusterForce * 0.22;
        nozzles[3].thrust = -pitchCmd * totalThrusterForce * 0.22;
      }
      // Also fire rear thrusters briefly to shift X toward the foot of the ramp (x ~ 8m)
      if (pos.x > 10.5 && fwd.x < -0.4) {
        nozzles[8].thrust = totalThrusterForce * 0.14;
        nozzles[9].thrust = totalThrusterForce * 0.14;
      }
      if (phaseTime >= 0.42 || pitchToLevel < 18 * DEG) {
        phase = "AIR_ROLL_AND_BRAKE";
        phaseTime = 0;
      }
    } else if (phase === "AIR_ROLL_AND_BRAKE") {
      fanCmd = 0.0;
      // We want the car horizontal facing -X: fwd = (-1, 0, 0), up = (0, 1, 0), right = (0, 0, -1).
      // Measure roll angle: when facing -X, right vector should be (0, 0, -1) and up should be (0, 1, 0).
      // Roll angle around body +X axis: atan2(-right.y, up.y)
      const rollErr = Math.atan2(-right.y, up.y); // ~ +-PI when inverted, 0 when upright!
      // Keep roll direction consistent (positive roll)
      const normRollErr = (rollErr < -0.35) ? (rollErr + 2 * Math.PI) : rollErr;
      const rollTorqueCmd = Math.max(-1, Math.min(1, normRollErr * 2.2 - omega.x * 0.42));

      if (rollTorqueCmd > 0.02) {
        nozzles[4].thrust = rollTorqueCmd * totalThrusterForce * 0.20;
        nozzles[5].thrust = rollTorqueCmd * totalThrusterForce * 0.20;
      } else if (rollTorqueCmd < -0.02) {
        nozzles[6].thrust = -rollTorqueCmd * totalThrusterForce * 0.20;
        nozzles[7].thrust = -rollTorqueCmd * totalThrusterForce * 0.20;
      }

      // Pitch and yaw stabilization using differential corner nozzles
      // Desired world up in body frame:
      const worldUpInBody = new Vec3(0, 1, 0).applyQuaternion(qInv);
      // Once the car is more than 100 deg rolled (up.y > 0.15), fire the 4 downward corner nozzles to brake the fall and hover briefly!
      let baseLift = 0;
      if (up.y > 0.15) {
        // Target descent velocity profile: hover briefly around y = 1.6m from phaseTime 1.1..1.7, then touch down gently
        const targetVy = (phaseTime < 1.55)
          ? Math.max(-9.0, Math.min(1.5, (1.65 - pos.y) * 2.6))
          : -1.45;
        const vyErr = targetVy - vel.y;
        const neededUpForce = mass * (gravity + Math.max(-gravity * 0.8, vyErr * 5.2)) / Math.max(0.35, up.y);
        baseLift = Math.max(0, Math.min(totalThrusterForce * 0.95, neededUpForce)) * 0.25;
      }

      // Attitude pitch stabilization (keep fwd.y -> 0)
      const pitchErr = -fwd.y; // if nose is too high (fwd.y > 0), pitchErr < 0 -> want nose down (-omega.z)
      const pitchDiff = (pitchErr * 3.2 - omega.z * 0.55) * totalThrusterForce * 0.08;
      // Roll assist from corner nozzles when nearly upright
      const rollDiff = (up.y > 0.3) ? (normRollErr * 1.4 - omega.x * 0.32) * totalThrusterForce * 0.07 : 0;

      nozzles[0].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLift + pitchDiff - rollDiff));
      nozzles[1].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLift + pitchDiff + rollDiff));
      nozzles[2].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLift - pitchDiff - rollDiff));
      nozzles[3].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLift - pitchDiff + rollDiff));

      // Keep X position near landing zone (x ~ 6..9m) using rear nozzles if needed
      if (pos.x > 9.5 && fwd.x < -0.7 && up.y > 0.3) {
        nozzles[8].thrust = totalThrusterForce * 0.08;
        nozzles[9].thrust = totalThrusterForce * 0.08;
      }

      if (wheelsInContact >= 3 && pos.y < 0.65 && Math.abs(vel.y) < 2.5) {
        phase = "TOUCHDOWN_DRIVE_OUT";
        phaseTime = 0;
        landedCleanly = !crashed;
      }
    } else if (phase === "TOUCHDOWN_DRIVE_OUT") {
      fanCmd = 0.25;
      if (phaseTime < 0.35) {
        // Settle suspension
        brakeCmd = 0.2;
      } else if (pos.x > -24.0) {
        // Drive out of the smoke cloud (-X direction, which is forward for the car now!)
        const targetDriveOutV = 13.5;
        if (fwdSpeed < targetDriveOutV) {
          driveForceCmd = mass * 7.5;
        }
      } else {
        // Come to a stop
        brakeCmd = 0.85;
      }
    }

    // --- PHYSICS INTEGRATION ---
    const force = new Vec3(0, -mass * gravity, 0);
    const torqueBody = new Vec3(0, 0, 0);

    // Aerodynamic drag
    const speed = vel.length();
    if (speed > 0.01) {
      force.addScaledVector(vel, -0.42 * speed);
    }

    // Fan Downforce (ground effect against nearest surface facing the floor)
    let currentDownforceN = 0;
    if (surf && fanCmd > 0) {
      const surfN = new Vec3(surf.nx, surf.ny, surf.nz);
      const align = surfN.dot(up);
      if (align > 0.2 && surf.dist < 1.6) {
        const distFactor = 1 / (1 + Math.pow(Math.max(0, surf.dist - 0.32) / 0.55, 2));
        currentDownforceN = fanCmd * (maxDownforceKg * 9.81) * distFactor * align;
        // Pull car toward surface (-surfN / -up)
        force.addScaledVector(surfN, -currentDownforceN);
      }
    }

    // Apply Nozzles (each nozzle pushes at its exact local position)
    for (const n of nozzles) {
      if (n.thrust > 0) {
        const fBody = new Vec3(n.fx * n.thrust, n.fy * n.thrust, n.fz * n.thrust);
        const rBody = new Vec3(n.lx, n.ly, n.lz);
        const tau = new Vec3().crossVectors(rBody, fBody);
        torqueBody.add(tau);
        const fWorld = fBody.clone().applyQuaternion(quat);
        force.add(fWorld);
      }
    }

    // Wheel Suspension & Tire Traction Forces
    const kSpring = mass * 34.0;
    const cDamper = mass * 4.8;
    const muTire = 1.18;

    for (const w of wheels) {
      const rBody = new Vec3(w.lx, w.ly, w.lz);
      const wPosWorld = rBody.clone().applyQuaternion(quat).add(pos);
      const wSurf = querySurface(wPosWorld.x, wPosWorld.y, wPosWorld.z);
      w.contact = false;
      w.load = 0;
      if (wSurf) {
        const sNorm = new Vec3(wSurf.nx, wSurf.ny, wSurf.nz);
        const align = sNorm.dot(up);
        const maxReach = w.restLen + w.radius;
        if (align > 0.25 && wSurf.dist <= maxReach && wSurf.dist > -0.25) {
          w.contact = true;
          const newComp = maxReach - wSurf.dist;
          const compRate = (newComp - w.comp) / dt;
          w.prevComp = w.comp;
          w.comp = newComp;

          // Point velocity of wheel contact patch
          const wVelBody = new Vec3().crossVectors(omega, rBody);
          const wVelWorld = wVelBody.applyQuaternion(quat).add(vel);
          const vNorm = wVelWorld.dot(sNorm);

          let fNorm = Math.max(0, kSpring * newComp - cDamper * vNorm);
          // Bottom-out bump stop if suspension compresses past 0.34m
          if (newComp > 0.34) {
            const bottomOut = (newComp - 0.34) * mass * 180 - Math.min(0, vNorm) * mass * 22;
            fNorm += Math.max(0, bottomOut);
            if (bottomOut * dt > maxImpactImpulse) maxImpactImpulse = bottomOut * dt;
          }
          w.load = fNorm;

          // Tire longitudinal & lateral forces in surface tangent plane
          const maxFriction = muTire * fNorm;
          const vTang = wVelWorld.clone().addScaledVector(sNorm, -vNorm);
          const wheelFwd = fwd.clone().addScaledVector(sNorm, -fwd.dot(sNorm)).normalize();
          const wheelRight = right.clone().addScaledVector(sNorm, -right.dot(sNorm)).normalize();

          const vLong = vTang.dot(wheelFwd);
          const vLat = vTang.dot(wheelRight);

          let fLong = (driveForceCmd * 0.25) - brakeCmd * Math.max(-maxFriction, Math.min(maxFriction, vLong * mass * 6.5));
          // Rolling damping
          fLong -= vLong * 35;
          const fLat = -vLat * mass * 8.5;

          // Friction circle clamp
          const fTangMag = Math.hypot(fLong, fLat);
          let scale = 1.0;
          if (fTangMag > maxFriction && fTangMag > 1e-5) {
            scale = maxFriction / fTangMag;
          }
          fLong *= scale;
          const fLatClamped = fLat * scale;

          const totalWheelFWorld = sNorm.clone().multiplyScalar(fNorm)
            .addScaledVector(wheelFwd, fLong)
            .addScaledVector(wheelRight, fLatClamped);

          force.add(totalWheelFWorld);
          const totalWheelFBody = totalWheelFWorld.clone().applyQuaternion(qInv);
          const wTau = new Vec3().crossVectors(rBody, totalWheelFBody);
          torqueBody.add(wTau);
        } else {
          w.comp = Math.max(0, w.comp - dt * 2.0);
        }
      }
    }

    // Chassis body hull collision points (roof, nose, tail, side sills)
    const hullPts = [
      { id: "ROOF_F", lx: +0.35, ly: +0.58, lz: 0.0 },
      { id: "ROOF_R", lx: -0.65, ly: +0.55, lz: 0.0 },
      { id: "NOSE_L", lx: +2.22, ly: +0.02, lz: -0.75 },
      { id: "NOSE_R", lx: +2.22, ly: +0.02, lz: +0.75 },
      { id: "TAIL_L", lx: -2.22, ly: +0.08, lz: -0.78 },
      { id: "TAIL_R", lx: -2.22, ly: +0.08, lz: +0.78 },
      { id: "SIDE_L", lx: 0.0, ly: +0.10, lz: -0.98 },
      { id: "SIDE_R", lx: 0.0, ly: +0.10, lz: +0.98 }
    ];

    for (const hp of hullPts) {
      const rBody = new Vec3(hp.lx, hp.ly, hp.lz);
      const pWorld = rBody.clone().applyQuaternion(quat).add(pos);
      const hSurf = querySurface(pWorld.x, pWorld.y, pWorld.z);
      if (hSurf && hSurf.dist < 0) {
        const pen = -hSurf.dist;
        const sNorm = new Vec3(hSurf.nx, hSurf.ny, hSurf.nz);
        const pVelBody = new Vec3().crossVectors(omega, rBody);
        const pVelWorld = pVelBody.applyQuaternion(quat).add(vel);
        const vNorm = pVelWorld.dot(sNorm);
        const fHullNorm = Math.max(0, pen * mass * 220 - Math.min(0, vNorm) * mass * 28);
        const impulse = fHullNorm * dt + (vNorm < -1.0 ? mass * (-vNorm) * 0.35 : 0);
        if (impulse > maxImpactImpulse) maxImpactImpulse = impulse;
        if (impulse > mass * 2.2) crashed = true;

        const vTang = pVelWorld.clone().addScaledVector(sNorm, -vNorm);
        const fHullWorld = sNorm.clone().multiplyScalar(fHullNorm).addScaledVector(vTang, -mass * 4.5);
        force.add(fHullWorld);
        const fHullBody = fHullWorld.clone().applyQuaternion(qInv);
        torqueBody.add(new Vec3().crossVectors(rBody, fHullBody));
      }
    }

    // Integrate linear velocity & position
    vel.addScaledVector(force, dt / mass);
    // Keep strictly on Z=0 lane when intact, allow 3D Z drift on crash
    if (!crashed) {
      force.z -= pos.z * mass * 15 + vel.z * mass * 6;
      torqueBody.y -= (fwd.z * 8.0 + omega.y * 4.0) * Iyy;
    }
    pos.addScaledVector(vel, dt);

    // Angular damping & gyroscopic integration in body frame
    omega.x += (torqueBody.x / Ixx - omega.x * 0.6) * dt;
    omega.y += (torqueBody.y / Iyy - omega.y * 0.8) * dt;
    omega.z += (torqueBody.z / Izz - omega.z * 0.6) * dt;

    const dq = new Quat(omega.x * 0.5 * dt, omega.y * 0.5 * dt, omega.z * 0.5 * dt, 0);
    dq.multiplyQuaternions(quat, dq);
    quat.x += dq.x; quat.y += dq.y; quat.z += dq.z; quat.w += dq.w;
    quat.normalize();
  }

  console.log(cfg.name, {
    finalPhase: phase,
    maxSReached: maxSReached.toFixed(2),
    maxPitchDeg: maxPitchDeg.toFixed(1),
    finalPos: [pos.x.toFixed(2), pos.y.toFixed(2)],
    maxImpactImpulse: Math.round(maxImpactImpulse),
    crashed,
    landedCleanly
  });
}

runTest({ name: "DEFAULT", mass: 2000, maxDownforceKg: 4700, entrySpeed: 23.5, totalThrusterForce: 72000, gravity: 9.81 });
runTest({ name: "LOW_DOWNFORCE", mass: 2000, maxDownforceKg: 950, entrySpeed: 23.5, totalThrusterForce: 72000, gravity: 9.81 });
runTest({ name: "THRUSTER_FAILURE", mass: 2000, maxDownforceKg: 4700, entrySpeed: 23.5, totalThrusterForce: 0, gravity: 9.81 });
runTest({ name: "TOO_SLOW", mass: 2000, maxDownforceKg: 4700, entrySpeed: 12.5, totalThrusterForce: 72000, gravity: 9.81 });
'

