      // Measure roll angle: when facing -X, right vector should be (0, 0, -1) and up should be (0, 1, 0).
      // Roll angle around body +X axis: atan2(-right.y, up.y)
      const rollErr = Math.atan2(-right.y, up.y); // ~ +-PI when inverted, 0 when upright!
      // Keep roll direction consistent (positive roll)
      const normRollErr = (rollErr < -0.35) ? (rollErr + 2 * Math.PI) : rollErr;
      const rollTorqueCmd = Math.max(-1, Math.min(1, normRollErr * 2.2 - omega.x * 0.42));

      if (rollTorqueCmd > 0.02) {
        nozzles[4].thrust = rollTorqueCmd * totalThrusterForce * 0.20;
        nozzles[5].thrust = rollTorqueCmd * totalThrusterForce * 0.20;
      } else if (rollTorqueCmd < -0.02) {
        nozzles[6].thrust = -rollTorqueCmd * totalThrusterForce * 0.20;
        nozzles[7].thrust = -rollTorqueCmd * totalThrusterForce * 0.20;
      }

      // Pitch and yaw stabilization using differential corner nozzles
      // Desired world up in body frame:
      const worldUpInBody = new Vec3(0, 1, 0).applyQuaternion(qInv);
      // Once the car is more than 100 deg rolled (up.y > 0.15), fire the 4 downward corner nozzles to brake the fall and hover briefly!
      let baseLift = 0;
      if (up.y > 0.15) {
        // Target descent velocity profile: hover briefly around y = 1.6m from phaseTime 1.1..1.7, then touch down gently
        const targetVy = (phaseTime < 1.55)
          ? Math.max(-9.0, Math.min(1.5, (1.65 - pos.y) * 2.6))
          : -1.45;
