node -e '
const DEG = Math.PI / 180;
const RAD = 180 / Math.PI;

class Vec3 {
  constructor(x=0, y=0, z=0) { this.x = x; this.y = y; this.z = z; }
  set(x,y,z) { this.x=x; this.y=y; this.z=z; return this; }
  copy(v) { this.x=v.x; this.y=v.y; this.z=v.z; return this; }
  clone() { return new Vec3(this.x, this.y, this.z); }
  add(v) { this.x+=v.x; this.y+=v.y; this.z+=v.z; return this; }
  sub(v) { this.x-=v.x; this.y-=v.y; this.z-=v.z; return this; }
  addScaledVector(v, s) { this.x+=v.x*s; this.y+=v.y*s; this.z+=v.z*s; return this; }
  multiplyScalar(s) { this.x*=s; this.y*=s; this.z*=s; return this; }
  dot(v) { return this.x*v.x + this.y*v.y + this.z*v.z; }
  crossVectors(a, b) {
    const ax=a.x, ay=a.y, az=a.z, bx=b.x, by=b.y, bz=b.z;
    this.x = ay*bz - az*by;
    this.y = az*bx - ax*bz;
    this.z = ax*by - ay*bx;
    return this;
  }
  length() { return Math.hypot(this.x, this.y, this.z); }
  normalize() { const l = this.length() || 1; return this.multiplyScalar(1/l); }
  applyQuaternion(q) {
    const x = this.x, y = this.y, z = this.z;
    const qx = q.x, qy = q.y, qz = q.z, qw = q.w;
    const ix = qw * x + qy * z - qz * y;
    const iy = qw * y + qz * x - qx * z;
    const iz = qw * z + qx * y - qy * x;
    const iw = -qx * x - qy * y - qz * z;
    this.x = ix * qw + iw * -qx + iy * -qz - iz * -qy;
    this.y = iy * qw + iw * -qy + iz * -qx - ix * -qz;
    this.z = iz * qw + iw * -qz + ix * -qy - iy * -qx;
    return this;
  }
}

class Quat {
  constructor(x=0, y=0, z=0, w=1) { this.x=x; this.y=y; this.z=z; this.w=w; }
  set(x,y,z,w) { this.x=x; this.y=y; this.z=z; this.w=w; return this; }
  copy(q) { this.x=q.x; this.y=q.y; this.z=q.z; this.w=q.w; return this; }
  clone() { return new Quat(this.x, this.y, this.z, this.w); }
  invert() { this.x=-this.x; this.y=-this.y; this.z=-this.z; return this; }
  normalize() {
    const l = Math.hypot(this.x, this.y, this.z, this.w) || 1;
    this.x/=l; this.y/=l; this.z/=l; this.w/=l;
    return this;
  }
  multiplyQuaternions(a, b) {
    const qax = a.x, qay = a.y, qaz = a.z, qaw = a.w;
    const qbx = b.x, qby = b.y, qbz = b.z, qbw = b.w;
    this.x = qax * qbw + qaw * qbx + qay * qbz - qaz * qby;
    this.y = qay * qbw + qaw * qby + qaz * qbx - qax * qbz;
    this.z = qaz * qbw + qaw * qbz + qax * qby - qay * qbx;
    this.w = qaw * qbw - qax * qbx - qay * qby - qaz * qbz;
    return this;
  }
}

function createRampGeometry() {
  const targetAngle = 115 * DEG;
  function rawWeight(u) {
    if (u < 0.06) return 0;
    if (u < 0.22) {
      const t = (u - 0.06) / 0.16;
      return (0.5 - 0.5 * Math.cos(Math.PI * t)) * 1.35;
    }
    if (u < 0.68) return 1.35;
    const t = (u - 0.68) / 0.32;
    return 1.35 * (1 - 0.52 * t);
  }
  const N = 2000;
  let integralW = 0;
  for (let i = 0; i < N; i++) integralW += rawWeight((i + 0.5) / N) / N;
  const kScale = targetAngle / integralW;
  let x = 0, y = 0, theta = 0;
  const rawPts = [{ u: 0, x: 0, y: 0, theta: 0, k: 0 }];
  for (let i = 0; i < N; i++) {
    const u = (i + 0.5) / N;
    const du = 1 / N;
    const k = kScale * rawWeight(u);
    theta += k * du;
    x += Math.cos(theta) * du;
    y += Math.sin(theta) * du;
    rawPts.push({ u: (i + 1) / N, x, y, theta, k });
  }
  const L = 20.0 / y;
  const pts = rawPts.map(p => ({
    s: p.u * L,
    x: p.x * L,
    y: p.y * L,
    theta: p.theta,
    k: p.k / L,
    tx: Math.cos(p.theta),
    ty: Math.sin(p.theta),
    nx: -Math.sin(p.theta),
    ny: Math.cos(p.theta)
  }));
  return {
    L,
    width: 6.2,
    pts,
    sampleAtS(s) {
      const cs = Math.max(0, Math.min(L, s));
      const idx = Math.min(N - 1, Math.floor((cs / L) * N));
      const frac = ((cs / L) * N) - idx;
      const a = pts[idx], b = pts[idx + 1];
      const theta = a.theta + (b.theta - a.theta) * frac;
      return {
        s: cs,
        x: a.x + (b.x - a.x) * frac,
        y: a.y + (b.y - a.y) * frac,
        theta,
        k: a.k + (b.k - a.k) * frac,
        tx: Math.cos(theta),
        ty: Math.sin(theta),
        nx: -Math.sin(theta),
        ny: Math.cos(theta)
      };
    },
    findClosest(px, py) {
      let bestIdx = 0, bestD2 = Infinity;
      const step = 20;
      for (let i = 0; i <= N; i += step) {
        const dx = px - pts[i].x, dy = py - pts[i].y;
        const d2 = dx*dx + dy*dy;
        if (d2 < bestD2) { bestD2 = d2; bestIdx = i; }
      }
      const lo = Math.max(0, bestIdx - step), hi = Math.min(N, bestIdx + step);
      for (let i = lo; i <= hi; i++) {
        const dx = px - pts[i].x, dy = py - pts[i].y;
        const d2 = dx*dx + dy*dy;
        if (d2 < bestD2) { bestD2 = d2; bestIdx = i; }
      }
      const p = pts[bestIdx];
      const dx = px - p.x, dy = py - p.y;
      const ds = dx * p.tx + dy * p.ty;
      const sRaw = p.s + ds;
      const s = Math.max(0, Math.min(L, sRaw));
      const exact = this.sampleAtS(s);
      const ex = px - exact.x, ey = py - exact.y;
      const signedDist = ex * exact.nx + ey * exact.ny;
      return { ...exact, sRaw, signedDist, distSq: ex*ex + ey*ey };
    }
  };
}

const ramp = createRampGeometry();

function querySurface(px, py, pz) {
  let rampSurf = null;
  if (Math.abs(pz) <= ramp.width * 0.52 && px > -0.5) {
    const r = ramp.findClosest(px, py);
    // Only consider ramp surface if within deck bounds and close to the surface
    if (r.sRaw >= -0.2 && r.sRaw <= ramp.L + 0.25 && r.signedDist >= -0.38 && r.signedDist < 1.8) {
      rampSurf = {
        type: "ramp",
        dist: r.signedDist,
        nx: r.nx, ny: r.ny, nz: 0,
        tx: r.tx, ty: r.ty, tz: 0,
        s: r.s, sRaw: r.sRaw, theta: r.theta, k: r.k,
        sx: r.x, sy: r.y, sz: pz
      };
    }
  }
  const groundSurf = {
    type: "ground",
    dist: py,
    nx: 0, ny: 1, nz: 0,
    tx: 1, ty: 0, tz: 0,
    s: Math.min(0, px), sRaw: px, theta: 0, k: 0,
    sx: px, sy: 0, sz: pz
  };
  if (rampSurf && rampSurf.s > 1.2) {
    if (py < 1.2 && py < rampSurf.dist) return groundSurf;
    return rampSurf;
  }
  if (rampSurf && rampSurf.dist < groundSurf.dist) return rampSurf;
  return groundSurf;
}

function runTest(cfg) {
  const mass = cfg.mass ?? 2000;
  const maxDownforceKg = cfg.maxDownforceKg ?? 4700;
  const entrySpeed = cfg.entrySpeed ?? 23.0;
  const totalThrusterForce = cfg.totalThrusterForce ?? 72000; // N
  const gravity = cfg.gravity ?? 9.81;

  const Ixx = mass * (2.0*2.0 + 1.15*1.15) / 12 * 1.1; // ~960
  const Iyy = mass * (4.5*4.5 + 2.0*2.0) / 12 * 0.95;  // ~3800
  const Izz = mass * (4.5*4.5 + 1.15*1.15) / 12 * 0.95; // ~3400

  const pos = new Vec3(-14.0, 0.43, 0);
  const vel = new Vec3(0, 0, 0);
  const quat = new Quat(0, 0, 0, 1);
  const omega = new Vec3(0, 0, 0);

  const wheels = [
    { id: "FL", lx: +1.42, ly: -0.10, lz: -0.84, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 },
    { id: "FR", lx: +1.42, ly: -0.10, lz: +0.84, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 },
    { id: "RL", lx: -1.40, ly: -0.10, lz: -0.86, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 },
    { id: "RR", lx: -1.40, ly: -0.10, lz: +0.86, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 }
  ];

  const nozzles = [
    { id: "FL_DOWN", lx: +1.35, ly: -0.32, lz: -0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    { id: "FR_DOWN", lx: +1.35, ly: -0.32, lz: +0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    { id: "RL_DOWN", lx: -1.35, ly: -0.32, lz: -0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    { id: "RR_DOWN", lx: -1.35, ly: -0.32, lz: +0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    // Roll nozzles at z = +-0.95 producing pure roll couple around body X axis + side jet look
    { id: "ROLL_POS_L", lx: 0.0, ly: +0.25, lz: -0.95, fx: 0, fy: -0.92, fz: +0.39, thrust: 0 },
    { id: "ROLL_POS_R", lx: 0.0, ly: -0.25, lz: +0.95, fx: 0, fy: +0.92, fz: -0.39, thrust: 0 },
    { id: "ROLL_NEG_L", lx: 0.0, ly: -0.25, lz: -0.95, fx: 0, fy: +0.92, fz: +0.39, thrust: 0 },
    { id: "ROLL_NEG_R", lx: 0.0, ly: +0.25, lz: +0.95, fx: 0, fy: -0.92, fz: -0.39, thrust: 0 },
    { id: "REAR_L", lx: -2.20, ly: -0.08, lz: -0.36, fx: 1, fy: 0.0, fz: 0, thrust: 0 },
    { id: "REAR_R", lx: -2.20, ly: -0.08, lz: +0.36, fx: 1, fy: 0.0, fz: 0, thrust: 0 }
  ];

  let phase = "WAIT_START";
  let phaseTime = 0;
  let maxSReached = -14;
  let maxHeight = 0;
  let maxPitchDeg = 0;
  let maxImpactImpulse = 0;
  let crashed = false;
  let landedCleanly = false;
  let hoverReached = false;
  const dt = 1 / 240;

  for (let step = 0; step < 240 * 14.5; step++) {
    const t = step * dt;
    phaseTime += dt;

    const fwd = new Vec3(1, 0, 0).applyQuaternion(quat);
    const up = new Vec3(0, 1, 0).applyQuaternion(quat);
    const right = new Vec3(0, 0, 1).applyQuaternion(quat);
    const qInv = quat.clone().invert();

    const surf = querySurface(pos.x, pos.y, pos.z);
    const onRamp = surf.type === "ramp";
    const sPos = onRamp ? surf.s : pos.x;
    if (sPos > maxSReached) maxSReached = sPos;
    if (pos.y > maxHeight) maxHeight = pos.y;

    const rampPitchDeg = Math.atan2(fwd.y, fwd.x) * RAD;
    if (onRamp && rampPitchDeg > maxPitchDeg) maxPitchDeg = rampPitchDeg;

    let driveForceCmd = 0;
    let brakeCmd = 0;
    let fanCmd = 0;
    for (const n of nozzles) n.thrust = 0;

    const fwdSpeed = vel.dot(fwd);
    const wheelsInContact = wheels.filter(w => w.contact).length;

    if (phase === "WAIT_START") {
      brakeCmd = 1.0;
      if (t >= 0.65) {
        phase = "CLIMB";
        phaseTime = 0;
      }
    } else if (phase === "CLIMB") {
      fanCmd = sPos > -2.0 ? 1.0 : 0.4;
      const targetS = 29.55; // hang position right near lip (theta = 111.5 deg, y = 18.2m)
      const remS = targetS - sPos;

      // In the approach & lower curve (s < 8m), accelerate to entrySpeed.
      // Above s = 8m (steep/vertical curve), drive power is capped by entrySpeed ratio so "Too Slow" cannot cheat up the wall!
      const speedRatio = Math.pow(Math.max(0.1, entrySpeed / 23.0), 2);
      const stopBrakeProfile = Math.sqrt(Math.max(0, 2 * 14.5 * Math.max(0, remS)));
      const targetV = Math.min(entrySpeed, stopBrakeProfile);
      const vErr = targetV - fwdSpeed;

      if (onRamp && remS <= 0.35 && Math.abs(fwdSpeed) < 1.0 && sPos > 27.5) {
        phase = "HANG";
        phaseTime = 0;
      } else if (wheelsInContact === 0 && pos.y > 2.5 && vel.y < -1.5) {
        phase = "FALL_ABORT";
        phaseTime = 0;
      } else if (sPos > 5.0 && fwdSpeed < -1.8) {
        phase = "SLIDE_BACK";
        phaseTime = 0;
      } else {
        if (sPos < 6.0) {
          // Accelerate to entrySpeed on approach
          if (vErr > 0) {
            driveForceCmd = Math.min(mass * 18.0 * speedRatio, vErr * mass * 5.0);
            if (sPos < 1.0 && entrySpeed >= 19.0 && vErr > 1.5) {
              nozzles[8].thrust = totalThrusterForce * 0.14;
              nozzles[9].thrust = totalThrusterForce * 0.14;
            }
          }
        } else {
          // Climbing the vertical curve: motor drive force is bounded by speedRatio
          if (vErr >= 0) {
            driveForceCmd = Math.min(mass * 9.8 * speedRatio, vErr * mass * 3.8 * speedRatio);
          } else {
            brakeCmd = Math.min(1.0, -vErr * 0.45);
          }
        }
      }
    } else if (phase === "HANG") {
      fanCmd = 1.0;
      brakeCmd = 1.0;
      if ((wheelsInContact === 0 && vel.y < -1.5) || fwdSpeed < -2.0) {
        phase = "FALL_ABORT";
        phaseTime = 0;
      } else if (phaseTime >= 2.0) {
        phase = "RELEASE_PITCH";
        phaseTime = 0;
      }
    } else if (phase === "RELEASE_PITCH") {
      // Release from lip: cut fans, push away from lip and pitch nose to horizontal belly-up facing -X!
      fanCmd = 0.0;
      brakeCmd = 0.0;
      // Angle needed to reach fwd = (-1, 0, 0) from current fwd in XY plane:
      const pitchToInvHoriz = Math.atan2(fwd.y, -fwd.x); // positive ~ 68 deg at start of release, 0 when horizontal facing -X
      const pitchRateCmd = Math.max(-4.5, Math.min(4.5, pitchToInvHoriz * 5.0));
      const pitchTorqueErr = pitchRateCmd - omega.z;

      // Fire FL_DOWN & FR_DOWN to push away from ramp lip AND pitch +omega.z!
      // Wait: at the lip, car up is (-0.93, -0.37, 0), which points LEFT (-X) and DOWN (-Y)!
      // So firing FL_DOWN & FR_DOWN (+up in body frame) pushes the car LEFT (-X, away from the ramp!) and pitches +omega.z!
      if (pitchTorqueErr > 0) {
        const f = Math.min(totalThrusterForce * 0.25, pitchTorqueErr * Izz * 2.8);
        nozzles[0].thrust = f;
        nozzles[1].thrust = f;
      } else {
        const f = Math.min(totalThrusterForce * 0.25, -pitchTorqueErr * Izz * 2.8);
        nozzles[2].thrust = f;
        nozzles[3].thrust = f;
      }
      // Also fire rear nozzles briefly as seen in frame 14 & 16!
      if (phaseTime < 0.35) {
        nozzles[8].thrust = totalThrusterForce * 0.12;
        nozzles[9].thrust = totalThrusterForce * 0.12;
      }

      if (phaseTime >= 0.48 && Math.abs(pitchToInvHoriz) < 16 * DEG) {
        phase = "AIR_ROLL_AND_BRAKE";
        phaseTime = 0;
      } else if (phaseTime >= 0.72) {
        phase = "AIR_ROLL_AND_BRAKE";
        phaseTime = 0;
      }
    } else if (phase === "AIR_ROLL_AND_BRAKE") {
      fanCmd = 0.0;
      // Roll control around body X axis to bring car from belly-up (roll = PI) to wheels-down (roll = 0)
      // Current roll angle relative to world up (0, 1, 0):
      const localUp = new Vec3(0, 1, 0).applyQuaternion(qInv);
      // In body frame, we want world up to align with +Y_body (0, 1, 0).
      // Roll angle error around body X axis: atan2(-localUp.z, localUp.y)
      let rollErr = Math.atan2(-localUp.z, localUp.y);
      // When belly-up (localUp.y < -0.5), always roll in the +X direction so it does a clean 180 deg roll
      if (rollErr < -0.4) rollErr += 2 * Math.PI;

      const targetRollRate = Math.max(-5.2, Math.min(5.2, rollErr * 4.2));
      const rollRateErr = targetRollRate - omega.x;
      const rollCmd = Math.max(-1, Math.min(1, rollRateErr * 0.55));

      if (rollCmd > 0.01) {
        nozzles[4].thrust = rollCmd * totalThrusterForce * 0.22;
        nozzles[5].thrust = rollCmd * totalThrusterForce * 0.22;
      } else if (rollCmd < -0.01) {
        nozzles[6].thrust = -rollCmd * totalThrusterForce * 0.22;
        nozzles[7].thrust = -rollCmd * totalThrusterForce * 0.22;
      }

      // Pitch & Yaw stabilization in body frame:
      // We want fwd to align with (-1, 0, 0) in world frame!
      const targetFwdInBody = new Vec3(-1, 0, 0).applyQuaternion(qInv);
      // Pitch error around body Z axis: targetFwdInBody.y
      const pitchErr = targetFwdInBody.y;
      const yawErr = -targetFwdInBody.z;

      const pitchTorqueCmd = (pitchErr * 6.5 - omega.z * 1.8) * Izz;
      const rollAssistCmd = (up.y > 0.25) ? (rollErr * 4.5 - omega.x * 1.4) * Ixx : 0;

      // Downward braking lift once car is mostly upright (up.y > 0.35)
      let baseLiftPerNozzle = 0;
      if (up.y > 0.35) {
        // Hover briefly at y = 1.6m around phaseTime 1.0..1.55s, then descend gently at -1.2 m/s
        let targetVy;
        if (phaseTime < 1.45) {
          targetVy = Math.max(-8.0, Math.min(1.0, (1.55 - pos.y) * 2.8));
          if (pos.y < 2.8 && Math.abs(vel.y) < 2.0) hoverReached = true;
        } else {
          targetVy = -1.25;
        }
        const ayCmd = gravity + (targetVy - vel.y) * 6.5;
        const totalLiftNeeded = Math.max(0, (mass * ayCmd) / Math.max(0.45, up.y));
        baseLiftPerNozzle = Math.min(totalThrusterForce * 0.25, totalLiftNeeded * 0.25);

        // Horizontal X drift damping during hover/braking so it lands cleanly at x ~ 7..9m
        if (Math.abs(vel.x) > 0.5 && pos.y < 8.0) {
          if (vel.x > 0.3) {
            nozzles[8].thrust = Math.min(totalThrusterForce * 0.12, vel.x * mass * 1.5);
            nozzles[9].thrust = nozzles[8].thrust;
          }
        }
      }

      const dPitch = pitchTorqueCmd / (4 * 1.35);
      const dRoll = rollAssistCmd / (4 * 0.82);

      nozzles[0].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle + dPitch - dRoll));
      nozzles[1].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle + dPitch + dRoll));
      nozzles[2].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle - dPitch - dRoll));
      nozzles[3].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle - dPitch + dRoll));

      if (wheelsInContact >= 3 && pos.y < 0.62 && up.y > 0.85 && Math.abs(vel.y) < 2.5) {
        phase = "TOUCHDOWN_DRIVE_OUT";
        phaseTime = 0;
        landedCleanly = !crashed;
      }
    } else if (phase === "TOUCHDOWN_DRIVE_OUT") {
      fanCmd = 0.2;
      if (phaseTime < 0.45) {
        // Absorb landing and pause briefly in smoke burst
        brakeCmd = 0.35;
      } else if (pos.x > -22.0) {
        // Drive out of the smoke cloud in -X!
        const targetDriveV = 13.0;
        if (fwdSpeed < targetDriveV) {
          driveForceCmd = mass * 7.8;
        }
      } else {
        brakeCmd = 0.9;
      }
    }

    // --- ACCUMULATE FORCES & TORQUES ---
    const force = new Vec3(0, -mass * gravity, 0);
    const torqueBody = new Vec3(0, 0, 0);

    const speed = vel.length();
    if (speed > 0.01) {
      force.addScaledVector(vel, -0.38 * speed);
    }

    // Fan Downforce
    if (surf && fanCmd > 0) {
      const surfN = new Vec3(surf.nx, surf.ny, surf.nz);
      const align = surfN.dot(up);
      if (align > 0.25 && surf.dist < 1.35) {
        const distFactor = 1 / (1 + Math.pow(Math.max(0, surf.dist - 0.34) / 0.48, 2));
        const dfN = fanCmd * (maxDownforceKg * 9.81) * distFactor * align;
        force.addScaledVector(surfN, -dfN);
      }
    }

    // Thruster Nozzles
    for (const n of nozzles) {
      if (n.thrust > 0) {
        const fBody = new Vec3(n.fx * n.thrust, n.fy * n.thrust, n.fz * n.thrust);
        const rBody = new Vec3(n.lx, n.ly, n.lz);
        torqueBody.add(new Vec3().crossVectors(rBody, fBody));
        force.add(fBody.clone().applyQuaternion(quat));
      }
    }

    // Wheels
    const kSpring = mass * 34.0;
    const cDamper = mass * 5.2;
    const muTire = 1.15;

    for (const w of wheels) {
      const rBody = new Vec3(w.lx, w.ly, w.lz);
      const wPosWorld = rBody.clone().applyQuaternion(quat).add(pos);
      const wSurf = querySurface(wPosWorld.x, wPosWorld.y, wPosWorld.z);
      w.contact = false;
      w.load = 0;
      if (wSurf) {
        const sNorm = new Vec3(wSurf.nx, wSurf.ny, wSurf.nz);
        const align = sNorm.dot(up);
        const maxReach = w.restLen + w.radius;
        if (align > 0.25 && wSurf.dist <= maxReach && wSurf.dist > -0.28) {
          w.contact = true;
          const newComp = maxReach - wSurf.dist;
          w.comp = newComp;

          const wVelBody = new Vec3().crossVectors(omega, rBody);
          const wVelWorld = wVelBody.applyQuaternion(quat).add(vel);
          const vNorm = wVelWorld.dot(sNorm);

          let fNorm = Math.max(0, kSpring * newComp - cDamper * vNorm);
          if (newComp > 0.34) {
            const bottomOut = (newComp - 0.34) * mass * 160 - Math.min(0, vNorm) * mass * 18;
            fNorm += Math.max(0, bottomOut);
            const imp = Math.max(0, bottomOut) * dt + (vNorm < -6.0 ? mass * (-vNorm - 6.0) * 0.25 : 0);
            if (imp > maxImpactImpulse) maxImpactImpulse = imp;
            if (imp > mass * 2.2) crashed = true;
          }
          w.load = fNorm;

          const maxFriction = muTire * fNorm;
          const vTang = wVelWorld.clone().addScaledVector(sNorm, -vNorm);
          const wheelFwd = fwd.clone().addScaledVector(sNorm, -fwd.dot(sNorm)).normalize();
          const wheelRight = right.clone().addScaledVector(sNorm, -right.dot(sNorm)).normalize();

          const vLong = vTang.dot(wheelFwd);
          const vLat = vTang.dot(wheelRight);

          let fLong = (driveForceCmd * 0.25) - brakeCmd * Math.max(-maxFriction, Math.min(maxFriction, vLong * mass * 6.5));
          fLong -= vLong * 28;
          const fLat = -vLat * mass * 8.5;

          const fTangMag = Math.hypot(fLong, fLat);
          let scale = 1.0;
          if (fTangMag > maxFriction && fTangMag > 1e-5) scale = maxFriction / fTangMag;
          fLong *= scale;
          const fLatClamped = fLat * scale;

          const totalWheelFWorld = sNorm.clone().multiplyScalar(fNorm)
            .addScaledVector(wheelFwd, fLong)
            .addScaledVector(wheelRight, fLatClamped);

          force.add(totalWheelFWorld);
          const totalWheelFBody = totalWheelFWorld.clone().applyQuaternion(qInv);
          torqueBody.add(new Vec3().crossVectors(rBody, totalWheelFBody));
        } else {
          w.comp = Math.max(0, w.comp - dt * 2.0);
        }
      }
    }

    // Hull collisions (roof, nose, tail, sides)
    const hullPts = [
      { id: "ROOF_F", lx: +0.35, ly: +0.58, lz: 0.0 },
      { id: "ROOF_R", lx: -0.65, ly: +0.55, lz: 0.0 },
      { id: "NOSE_L", lx: +2.22, ly: +0.02, lz: -0.75 },
      { id: "NOSE_R", lx: +2.22, ly: +0.02, lz: +0.75 },
      { id: "TAIL_L", lx: -2.22, ly: +0.08, lz: -0.78 },
      { id: "TAIL_R", lx: -2.22, ly: +0.08, lz: +0.78 },
      { id: "SIDE_L", lx: 0.0, ly: +0.10, lz: -0.98 },
      { id: "SIDE_R", lx: 0.0, ly: +0.10, lz: +0.98 }
    ];

    for (const hp of hullPts) {
      const rBody = new Vec3(hp.lx, hp.ly, hp.lz);
      const pWorld = rBody.clone().applyQuaternion(quat).add(pos);
      const hSurf = querySurface(pWorld.x, pWorld.y, pWorld.z);
      if (hSurf && hSurf.dist < 0) {
        const pen = -hSurf.dist;
        const sNorm = new Vec3(hSurf.nx, hSurf.ny, hSurf.nz);
        const pVelBody = new Vec3().crossVectors(omega, rBody);
        const pVelWorld = pVelBody.applyQuaternion(quat).add(vel);
        const vNorm = pVelWorld.dot(sNorm);
        const fHullNorm = Math.max(0, pen * mass * 220 - Math.min(0, vNorm) * mass * 28);
        const impulse = fHullNorm * dt + (vNorm < -1.5 ? mass * (-vNorm) * 0.45 : 0);
        if (impulse > maxImpactImpulse) maxImpactImpulse = impulse;
        if (impulse > mass * 2.0) crashed = true;

        const vTang = pVelWorld.clone().addScaledVector(sNorm, -vNorm);
        const fHullWorld = sNorm.clone().multiplyScalar(fHullNorm).addScaledVector(vTang, -mass * 4.5);
        force.add(fHullWorld);
        const fHullBody = fHullWorld.clone().applyQuaternion(qInv);
        torqueBody.add(new Vec3().crossVectors(rBody, fHullBody));
      }
    }

    if (!crashed) {
      force.z -= pos.z * mass * 15 + vel.z * mass * 6;
      torqueBody.y -= (fwd.z * 8.0 + omega.y * 4.0) * Iyy;
    }

    vel.addScaledVector(force, dt / mass);
    pos.addScaledVector(vel, dt);

    omega.x += (torqueBody.x / Ixx - omega.x * 0.5) * dt;
    omega.y += (torqueBody.y / Iyy - omega.y * 0.8) * dt;
    omega.z += (torqueBody.z / Izz - omega.z * 0.5) * dt;

    const dq = new Quat(omega.x * 0.5 * dt, omega.y * 0.5 * dt, omega.z * 0.5 * dt, 0);
    dq.multiplyQuaternions(quat, dq);
    quat.x += dq.x; quat.y += dq.y; quat.z += dq.z; quat.w += dq.w;
    quat.normalize();
  }

  console.log(cfg.name, {
    finalPhase: phase,
    maxSReached: maxSReached.toFixed(2),
    maxHeight: maxHeight.toFixed(2),
    maxPitchDeg: maxPitchDeg.toFixed(1),
    finalPos: [pos.x.toFixed(2), pos.y.toFixed(2)],
    maxImpactImpulse: Math.round(maxImpactImpulse),
    hoverReached,
    crashed,
    landedCleanly
  });
}

runTest({ name: "DEFAULT", mass: 2000, maxDownforceKg: 4700, entrySpeed: 23.0, totalThrusterForce: 72000, gravity: 9.81 });
runTest({ name: "LOW_DOWNFORCE", mass: 2000, maxDownforceKg: 950, entrySpeed: 23.0, totalThrusterForce: 72000, gravity: 9.81 });
runTest({ name: "THRUSTER_FAILURE", mass: 2000, maxDownforceKg: 4700, entrySpeed: 23.0, totalThrusterForce: 0, gravity: 9.81 });
runTest({ name: "TOO_SLOW", mass: 2000, maxDownforceKg: 4700, entrySpeed: 12.5, totalThrusterForce: 72000, gravity: 9.81 });
'

args.command:
node -e '
const DEG = Math.PI / 180;
const RAD = 180 / Math.PI;

class Vec3 {
  constructor(x=0, y=0, z=0) { this.x = x; this.y = y; this.z = z; }
  set(x,y,z) { this.x=x; this.y=y; this.z=z; return this; }
  copy(v) { this.x=v.x; this.y=v.y; this.z=v.z; return this; }
  clone() { return new Vec3(this.x, this.y, this.z); }
  add(v) { this.x+=v.x; this.y+=v.y; this.z+=v.z; return this; }
  sub(v) { this.x-=v.x; this.y-=v.y; this.z-=v.z; return this; }
  addScaledVector(v, s) { this.x+=v.x*s; this.y+=v.y*s; this.z+=v.z*s; return this; }
  multiplyScalar(s) { this.x*=s; this.y*=s; this.z*=s; return this; }
  dot(v) { return this.x*v.x + this.y*v.y + this.z*v.z; }
  crossVectors(a, b) {
    const ax=a.x, ay=a.y, az=a.z, bx=b.x, by=b.y, bz=b.z;
    this.x = ay*bz - az*by;
    this.y = az*bx - ax*bz;
    this.z = ax*by - ay*bx;
    return this;
  }
  length() { return Math.hypot(this.x, this.y, this.z); }
  normalize() { const l = this.length() || 1; return this.multiplyScalar(1/l); }
  applyQuaternion(q) {
    const x = this.x, y = this.y, z = this.z;
    const qx = q.x, qy = q.y, qz = q.z, qw = q.w;
    const ix = qw * x + qy * z - qz * y;
    const iy = qw * y + qz * x - qx * z;
    const iz = qw * z + qx * y - qy * x;
    const iw = -qx * x - qy * y - qz * z;
    this.x = ix * qw + iw * -qx + iy * -qz - iz * -qy;
    this.y = iy * qw + iw * -qy + iz * -qx - ix * -qz;
    this.z = iz * qw + iw * -qz + ix * -qy - iy * -qx;
    return this;
  }
}

class Quat {
  constructor(x=0, y=0, z=0, w=1) { this.x=x; this.y=y; this.z=z; this.w=w; }
  set(x,y,z,w) { this.x=x; this.y=y; this.z=z; this.w=w; return this; }
  copy(q) { this.x=q.x; this.y=q.y; this.z=q.z; this.w=q.w; return this; }
  clone() { return new Quat(this.x, this.y, this.z, this.w); }
  invert() { this.x=-this.x; this.y=-this.y; this.z=-this.z; return this; }
  normalize() {
    const l = Math.hypot(this.x, this.y, this.z, this.w) || 1;
    this.x/=l; this.y/=l; this.z/=l; this.w/=l;
    return this;
  }
  multiplyQuaternions(a, b) {
    const qax = a.x, qay = a.y, qaz = a.z, qaw = a.w;
    const qbx = b.x, qby = b.y, qbz = b.z, qbw = b.w;
    this.x = qax * qbw + qaw * qbx + qay * qbz - qaz * qby;
    this.y = qay * qbw + qaw * qby + qaz * qbx - qax * qbz;
    this.z = qaz * qbw + qaw * qbz + qax * qby - qay * qbx;
    this.w = qaw * qbw - qax * qbx - qay * qby - qaz * qbz;
    return this;
  }
}

function createRampGeometry() {
  const targetAngle = 115 * DEG;
  function rawWeight(u) {
    if (u < 0.06) return 0;
    if (u < 0.22) {
      const t = (u - 0.06) / 0.16;
      return (0.5 - 0.5 * Math.cos(Math.PI * t)) * 1.35;
    }
    if (u < 0.68) return 1.35;
    const t = (u - 0.68) / 0.32;
    return 1.35 * (1 - 0.52 * t);
  }
  const N = 2000;
  let integralW = 0;
  for (let i = 0; i < N; i++) integralW += rawWeight((i + 0.5) / N) / N;
  const kScale = targetAngle / integralW;
  let x = 0, y = 0, theta = 0;
  const rawPts = [{ u: 0, x: 0, y: 0, theta: 0, k: 0 }];
  for (let i = 0; i < N; i++) {
    const u = (i + 0.5) / N;
    const du = 1 / N;
    const k = kScale * rawWeight(u);
    theta += k * du;
    x += Math.cos(theta) * du;
    y += Math.sin(theta) * du;
    rawPts.push({ u: (i + 1) / N, x, y, theta, k });
  }
  const L = 20.0 / y;
  const pts = rawPts.map(p => ({
    s: p.u * L,
    x: p.x * L,
    y: p.y * L,
    theta: p.theta,
    k: p.k / L,
    tx: Math.cos(p.theta),
    ty: Math.sin(p.theta),
    nx: -Math.sin(p.theta),
    ny: Math.cos(p.theta)
  }));
  return {
    L,
    width: 6.2,
    pts,
    sampleAtS(s) {
      const cs = Math.max(0, Math.min(L, s));
      const idx = Math.min(N - 1, Math.floor((cs / L) * N));
      const frac = ((cs / L) * N) - idx;
      const a = pts[idx], b = pts[idx + 1];
      const theta = a.theta + (b.theta - a.theta) * frac;
      return {
        s: cs,
        x: a.x + (b.x - a.x) * frac,
        y: a.y + (b.y - a.y) * frac,
        theta,
        k: a.k + (b.k - a.k) * frac,
        tx: Math.cos(theta),
        ty: Math.sin(theta),
        nx: -Math.sin(theta),
        ny: Math.cos(theta)
      };
    },
    findClosest(px, py) {
      let bestIdx = 0, bestD2 = Infinity;
      const step = 20;
      for (let i = 0; i <= N; i += step) {
        const dx = px - pts[i].x, dy = py - pts[i].y;
        const d2 = dx*dx + dy*dy;
        if (d2 < bestD2) { bestD2 = d2; bestIdx = i; }
      }
      const lo = Math.max(0, bestIdx - step), hi = Math.min(N, bestIdx + step);
      for (let i = lo; i <= hi; i++) {
        const dx = px - pts[i].x, dy = py - pts[i].y;
        const d2 = dx*dx + dy*dy;
        if (d2 < bestD2) { bestD2 = d2; bestIdx = i; }
      }
      const p = pts[bestIdx];
      const dx = px - p.x, dy = py - p.y;
      const ds = dx * p.tx + dy * p.ty;
      const sRaw = p.s + ds;
      const s = Math.max(0, Math.min(L, sRaw));
      const exact = this.sampleAtS(s);
      const ex = px - exact.x, ey = py - exact.y;
      const signedDist = ex * exact.nx + ey * exact.ny;
      return { ...exact, sRaw, signedDist, distSq: ex*ex + ey*ey };
    }
  };
}

const ramp = createRampGeometry();

function querySurface(px, py, pz) {
  let rampSurf = null;
  if (Math.abs(pz) <= ramp.width * 0.52 && px > -0.5) {
    const r = ramp.findClosest(px, py);
    // Only consider ramp surface if within deck bounds and close to the surface
    if (r.sRaw >= -0.2 && r.sRaw <= ramp.L + 0.25 && r.signedDist >= -0.38 && r.signedDist < 1.8) {
      rampSurf = {
        type: "ramp",
        dist: r.signedDist,
        nx: r.nx, ny: r.ny, nz: 0,
        tx: r.tx, ty: r.ty, tz: 0,
        s: r.s, sRaw: r.sRaw, theta: r.theta, k: r.k,
        sx: r.x, sy: r.y, sz: pz
      };
    }
  }
  const groundSurf = {
    type: "ground",
    dist: py,
    nx: 0, ny: 1, nz: 0,
    tx: 1, ty: 0, tz: 0,
    s: Math.min(0, px), sRaw: px, theta: 0, k: 0,
    sx: px, sy: 0, sz: pz
  };
  if (rampSurf && rampSurf.s > 1.2) {
    if (py < 1.2 && py < rampSurf.dist) return groundSurf;
    return rampSurf;
  }
  if (rampSurf && rampSurf.dist < groundSurf.dist) return rampSurf;
  return groundSurf;
}

function runTest(cfg) {
  const mass = cfg.mass ?? 2000;
  const maxDownforceKg = cfg.maxDownforceKg ?? 4700;
  const entrySpeed = cfg.entrySpeed ?? 23.0;
  const totalThrusterForce = cfg.totalThrusterForce ?? 72000; // N
  const gravity = cfg.gravity ?? 9.81;

  const Ixx = mass * (2.0*2.0 + 1.15*1.15) / 12 * 1.1; // ~960
  const Iyy = mass * (4.5*4.5 + 2.0*2.0) / 12 * 0.95;  // ~3800
  const Izz = mass * (4.5*4.5 + 1.15*1.15) / 12 * 0.95; // ~3400

  const pos = new Vec3(-14.0, 0.43, 0);
  const vel = new Vec3(0, 0, 0);
  const quat = new Quat(0, 0, 0, 1);
  const omega = new Vec3(0, 0, 0);

  const wheels = [
    { id: "FL", lx: +1.42, ly: -0.10, lz: -0.84, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 },
    { id: "FR", lx: +1.42, ly: -0.10, lz: +0.84, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 },
    { id: "RL", lx: -1.40, ly: -0.10, lz: -0.86, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 },
    { id: "RR", lx: -1.40, ly: -0.10, lz: +0.86, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 }
  ];

  const nozzles = [
    { id: "FL_DOWN", lx: +1.35, ly: -0.32, lz: -0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    { id: "FR_DOWN", lx: +1.35, ly: -0.32, lz: +0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    { id: "RL_DOWN", lx: -1.35, ly: -0.32, lz: -0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    { id: "RR_DOWN", lx: -1.35, ly: -0.32, lz: +0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    // Roll nozzles at z = +-0.95 producing pure roll couple around body X axis + side jet look
    { id: "ROLL_POS_L", lx: 0.0, ly: +0.25, lz: -0.95, fx: 0, fy: -0.92, fz: +0.39, thrust: 0 },
    { id: "ROLL_POS_R", lx: 0.0, ly: -0.25, lz: +0.95, fx: 0, fy: +0.92, fz: -0.39, thrust: 0 },
    { id: "ROLL_NEG_L", lx: 0.0, ly: -0.25, lz: -0.95, fx: 0, fy: +0.92, fz: +0.39, thrust: 0 },
    { id: "ROLL_NEG_R", lx: 0.0, ly: +0.25, lz: +0.95, fx: 0, fy: -0.92, fz: -0.39, thrust: 0 },
    { id: "REAR_L", lx: -2.20, ly: -0.08, lz: -0.36, fx: 1, fy: 0.0, fz: 0, thrust: 0 },
    { id: "REAR_R", lx: -2.20, ly: -0.08, lz: +0.36, fx: 1, fy: 0.0, fz: 0, thrust: 0 }
  ];

  let phase = "WAIT_START";
  let phaseTime = 0;
  let maxSReached = -14;
  let maxHeight = 0;
  let maxPitchDeg = 0;
  let maxImpactImpulse = 0;
  let crashed = false;
  let landedCleanly = false;
  let hoverReached = false;
  const dt = 1 / 240;

  for (let step = 0; step < 240 * 14.5; step++) {
    const t = step * dt;
    phaseTime += dt;

    const fwd = new Vec3(1, 0, 0).applyQuaternion(quat);
    const up = new Vec3(0, 1, 0).applyQuaternion(quat);
    const right = new Vec3(0, 0, 1).applyQuaternion(quat);
    const qInv = quat.clone().invert();

    const surf = querySurface(pos.x, pos.y, pos.z);
    const onRamp = surf.type === "ramp";
    const sPos = onRamp ? surf.s : pos.x;
    if (sPos > maxSReached) maxSReached = sPos;
    if (pos.y > maxHeight) maxHeight = pos.y;

    const rampPitchDeg = Math.atan2(fwd.y, fwd.x) * RAD;
    if (onRamp && rampPitchDeg > maxPitchDeg) maxPitchDeg = rampPitchDeg;

    let driveForceCmd = 0;
    let brakeCmd = 0;
    let fanCmd = 0;
    for (const n of nozzles) n.thrust = 0;

    const fwdSpeed = vel.dot(fwd);
    const wheelsInContact = wheels.filter(w => w.contact).length;

    if (phase === "WAIT_START") {
      brakeCmd = 1.0;
      if (t >= 0.65) {
        phase = "CLIMB";
        phaseTime = 0;
      }
    } else if (phase === "CLIMB") {
      fanCmd = sPos > -2.0 ? 1.0 : 0.4;
      const targetS = 29.55; // hang position right near lip (theta = 111.5 deg, y = 18.2m)
      const remS = targetS - sPos;

      // In the approach & lower curve (s < 8m), accelerate to entrySpeed.
      // Above s = 8m (steep/vertical curve), drive power is capped by entrySpeed ratio so "Too Slow" cannot cheat up the wall!
      const speedRatio = Math.pow(Math.max(0.1, entrySpeed / 23.0), 2);
      const stopBrakeProfile = Math.sqrt(Math.max(0, 2 * 14.5 * Math.max(0, remS)));
      const targetV = Math.min(entrySpeed, stopBrakeProfile);
      const vErr = targetV - fwdSpeed;

      if (onRamp && remS <= 0.35 && Math.abs(fwdSpeed) < 1.0 && sPos > 27.5) {
        phase = "HANG";
        phaseTime = 0;
      } else if (wheelsInContact === 0 && pos.y > 2.5 && vel.y < -1.5) {
        phase = "FALL_ABORT";
        phaseTime = 0;
      } else if (sPos > 5.0 && fwdSpeed < -1.8) {
        phase = "SLIDE_BACK";
        phaseTime = 0;
      } else {
        if (sPos < 6.0) {
          // Accelerate to entrySpeed on approach
          if (vErr > 0) {
            driveForceCmd = Math.min(mass * 18.0 * speedRatio, vErr * mass * 5.0);
            if (sPos < 1.0 && entrySpeed >= 19.0 && vErr > 1.5) {
              nozzles[8].thrust = totalThrusterForce * 0.14;
              nozzles[9].thrust = totalThrusterForce * 0.14;
            }
          }
        } else {
          // Climbing the vertical curve: motor drive force is bounded by speedRatio
          if (vErr >= 0) {
            driveForceCmd = Math.min(mass * 9.8 * speedRatio, vErr * mass * 3.8 * speedRatio);
          } else {
            brakeCmd = Math.min(1.0, -vErr * 0.45);
          }
        }
      }
    } else if (phase === "HANG") {
      fanCmd = 1.0;
      brakeCmd = 1.0;
      if ((wheelsInContact === 0 && vel.y < -1.5) || fwdSpeed < -2.0) {
        phase = "FALL_ABORT";
        phaseTime = 0;
      } else if (phaseTime >= 2.0) {
        phase = "RELEASE_PITCH";
        phaseTime = 0;
      }
    } else if (phase === "RELEASE_PITCH") {
      // Release from lip: cut fans, push away from lip and pitch nose to horizontal belly-up facing -X!
      fanCmd = 0.0;
      brakeCmd = 0.0;
      // Angle needed to reach fwd = (-1, 0, 0) from current fwd in XY plane:
      const pitchToInvHoriz = Math.atan2(fwd.y, -fwd.x); // positive ~ 68 deg at start of release, 0 when horizontal facing -X
      const pitchRateCmd = Math.max(-4.5, Math.min(4.5, pitchToInvHoriz * 5.0));
      const pitchTorqueErr = pitchRateCmd - omega.z;

      // Fire FL_DOWN & FR_DOWN to push away from ramp lip AND pitch +omega.z!
      // Wait: at the lip, car up is (-0.93, -0.37, 0), which points LEFT (-X) and DOWN (-Y)!
      // So firing FL_DOWN & FR_DOWN (+up in body frame) pushes the car LEFT (-X, away from the ramp!) and pitches +omega.z!
      if (pitchTorqueErr > 0) {
        const f = Math.min(totalThrusterForce * 0.25, pitchTorqueErr * Izz * 2.8);
        nozzles[0].thrust = f;
        nozzles[1].thrust = f;
      } else {
        const f = Math.min(totalThrusterForce * 0.25, -pitchTorqueErr * Izz * 2.8);
        nozzles[2].thrust = f;
        nozzles[3].thrust = f;
      }
      // Also fire rear nozzles briefly as seen in frame 14 & 16!
      if (phaseTime < 0.35) {
        nozzles[8].thrust = totalThrusterForce * 0.12;
        nozzles[9].thrust = totalThrusterForce * 0.12;
      }

      if (phaseTime >= 0.48 && Math.abs(pitchToInvHoriz) < 16 * DEG) {
        phase = "AIR_ROLL_AND_BRAKE";
        phaseTime = 0;
      } else if (phaseTime >= 0.72) {
        phase = "AIR_ROLL_AND_BRAKE";
        phaseTime = 0;
      }
    } else if (phase === "AIR_ROLL_AND_BRAKE") {
      fanCmd = 0.0;
      // Roll control around body X axis to bring car from belly-up (roll = PI) to wheels-down (roll = 0)
      // Current roll angle relative to world up (0, 1, 0):
      const localUp = new Vec3(0, 1, 0).applyQuaternion(qInv);
      // In body frame, we want world up to align with +Y_body (0, 1, 0).
      // Roll angle error around body X axis: atan2(-localUp.z, localUp.y)
