        phaseTime = 0;
      } else if (wheelsInContact === 0 && pos.y > 2.5 && vel.y < -1.5) {
        phase = "FALL_ABORT";
        phaseTime = 0;
      } else if (sPos > 5.0 && fwdSpeed < -1.8) {
        phase = "SLIDE_BACK";
        phaseTime = 0;
      } else {
        if (sPos < 6.0) {
