args.command:
node -e '
const DEG = Math.PI / 180;
const RAD = 180 / Math.PI;

function createRampGeometry() {
  const targetAngle = 115 * DEG;
  // Tighter lower curve (0 -> 90 deg) and sweeping upper hook (90 -> 115 deg)
  function rawWeight(u) {
    if (u < 0.03) return 0;
    if (u < 0.14) {
      const t = (u - 0.03) / 0.11;
      return (0.5 - 0.5 * Math.cos(Math.PI * t)) * 2.35;
    }
    if (u < 0.48) return 2.35;
    const t = (u - 0.48) / 0.52;
    // Smoothly transition to gentler curvature in the upper vertical/hook section
    return 2.35 * (1 - 0.72 * (0.5 - 0.5 * Math.cos(Math.PI * t)));
  }
  const N = 2000;
  let integralW = 0;
  for (let i = 0; i < N; i++) integralW += rawWeight((i + 0.5) / N) / N;
  const kScale = targetAngle / integralW;
  let x = 0, y = 0, theta = 0, maxX = 0, yAt90 = 0;
  const rawPts = [{ u: 0, x: 0, y: 0, theta: 0, k: 0 }];
  for (let i = 0; i < N; i++) {
    const u = (i + 0.5) / N;
    const du = 1 / N;
    const k = kScale * rawWeight(u);
    const prevTheta = theta;
    theta += k * du;
    x += Math.cos(theta) * du;
    y += Math.sin(theta) * du;
    if (x > maxX) maxX = x;
    if (prevTheta < 90 * DEG && theta >= 90 * DEG) yAt90 = y;
    rawPts.push({ u: (i + 1) / N, x, y, theta, k });
  }
  const L = 20.0 / y;
  console.log({
    L: L.toFixed(2),
    maxX: (maxX * L).toFixed(2),
    endX: (x * L).toFixed(2),
    overhang: ((maxX - x) * L).toFixed(2),
    yAt90: (yAt90 * L).toFixed(2),
    endY: (y * L).toFixed(2),
    endDeg: (theta * RAD).toFixed(2)
  });
}
createRampGeometry();
'

