        s: cs,
        x: a.x + (b.x - a.x) * frac,
        y: a.y + (b.y - a.y) * frac,
        theta,
        k: a.k + (b.k - a.k) * frac,
        tx: Math.cos(theta),
        ty: Math.sin(theta),
        nx: -Math.sin(theta),
        ny: Math.cos(theta)
