      if (rollErr < -0.45) rollErr += 2 * Math.PI; // positive roll from PI -> 0

      const targetRollRate = Math.max(-5.5, Math.min(5.5, rollErr * 4.5));
      const rollRateErr = targetRollRate - omega.x;
      const rollCmd = Math.max(-1, Math.min(1, rollRateErr * 0.65));

      if (rollCmd > 0.01) {
        nozzles[4].thrust = rollCmd * totalThrusterForce * 0.24;
        nozzles[5].thrust = rollCmd * totalThrusterForce * 0.24;
      } else if (rollCmd < -0.01) {
        nozzles[6].thrust = -rollCmd * totalThrusterForce * 0.24;
        nozzles[7].thrust = -rollCmd * totalThrusterForce * 0.24;
      }

      // Pitch & Yaw stabilization in body frame so nose stays level pointing -X:
      // Target forward vector (-1, 0, 0) expressed in body coordinates:
      const targetFwdBody = new Vec3(-1, 0, 0).applyQuaternion(qInv);
      // Notice: if targetFwdBody.y > 0, the target (-1,0,0) is in the +Y_body direction, so we need +omega.z (nose up in body frame)!
      // And if targetFwdBody.z > 0, the target is in the +Z_body direction, so we need -omega.y!
      const pitchTorqueCmd = (targetFwdBody.y * 9.0 - omega.z * 2.4) * Izz;
      const yawTorqueCmd = (-targetFwdBody.z * 8.0 - omega.y * 2.4) * Iyy;
      const rollAssistCmd = (up.y > 0.2) ? (rollErr * 5.0 - omega.x * 1.6) * Ixx : 0;

      // Downward braking lift once car rolls past horizontal (up.y > 0.25)
      let baseLiftPerNozzle = 0;
      if (up.y > 0.25) {
        let targetVy;
        if (phaseTime < 1.55) {
          targetVy = Math.max(-8.5, Math.min(0.8, (1.45 - pos.y) * 2.8));
          if (pos.y < 2.6 && Math.abs(vel.y) < 1.8) hoverReached = true;
        } else {
          targetVy = -1.25;
        }
        const ayCmd = gravity + (targetVy - vel.y) * 6.8;
        const totalLiftNeeded = Math.max(0, (mass * ayCmd) / Math.max(0.45, up.y));
        baseLiftPerNozzle = Math.min(totalThrusterForce * 0.25, totalLiftNeeded * 0.25);

        // Damp horizontal X velocity so touchdown is nearly vertical at the foot of the ramp
        if (vel.x < -2.2 && fwd.x < -0.7) {
          // Moving left too fast: lightly brake or pitch slightly
        } else if (vel.x > -0.5 && pos.x > 1.5 && fwd.x < -0.7) {
          nozzles[8].thrust = totalThrusterForce * 0.08;
          nozzles[9].thrust = totalThrusterForce * 0.08;
        }
      }

      const dPitch = pitchTorqueCmd / (4 * 1.35);
      const dRoll = rollAssistCmd / (4 * 0.82);

      nozzles[0].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle + dPitch - dRoll));
      nozzles[1].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle + dPitch + dRoll));
      nozzles[2].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle - dPitch - dRoll));
      nozzles[3].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle - dPitch + dRoll));

      if (wheelsInContact >= 3 && pos.y < 0.60 && up.y > 0.88 && Math.abs(vel.y) < 2.8) {
        phase = "TOUCHDOWN_DRIVE_OUT";
        phaseTime = 0;
        landedCleanly = !crashed;
      }
    } else if (phase === "TOUCHDOWN_DRIVE_OUT") {
      fanCmd = 0.2;
      if (phaseTime < 0.45) {
        brakeCmd = 0.4;
      } else if (pos.x > -24.0) {
        const targetDriveV = 13.5;
        if (fwdSpeed < targetDriveV) {
          driveForceCmd = mass * 8.0;
        }
      } else {
        brakeCmd = 0.95;
      }
    }

    // --- ACCUMULATE FORCES & TORQUES ---
    const force = new Vec3(0, -mass * gravity, 0);
    const torqueBody = new Vec3(0, 0, 0);

    const speed = vel.length();
    if (speed > 0.01) {
      force.addScaledVector(vel, -0.38 * speed);
    }

    // Fan Downforce
    if (surf && fanCmd > 0) {
      const surfN = new Vec3(surf.nx, surf.ny, surf.nz);
      const align = surfN.dot(up);
      if (align > 0.25 && surf.dist < 1.25) {
        const distFactor = 1 / (1 + Math.pow(Math.max(0, surf.dist - 0.34) / 0.45, 2));
        const dfN = fanCmd * (maxDownforceKg * 9.81) * distFactor * align;
        force.addScaledVector(surfN, -dfN);
      }
    }

    // Thrusters
    for (const n of nozzles) {
      if (n.thrust > 0) {
        const fBody = new Vec3(n.fx * n.thrust, n.fy * n.thrust, n.fz * n.thrust);
        const rBody = new Vec3(n.lx, n.ly, n.lz);
        torqueBody.add(new Vec3().crossVectors(rBody, fBody));
        force.add(fBody.clone().applyQuaternion(quat));
      }
    }

    // Wheels
    const kSpring = mass * 34.0;
    const cDamper = mass * 5.2;
    const muTire = 1.15;

    for (const w of wheels) {
      const rBody = new Vec3(w.lx, w.ly, w.lz);
      const wPosWorld = rBody.clone().applyQuaternion(quat).add(pos);
      const wSurf = querySurface(wPosWorld.x, wPosWorld.y, wPosWorld.z);
      w.contact = false;
      w.load = 0;
      if (wSurf) {
        const sNorm = new Vec3(wSurf.nx, wSurf.ny, wSurf.nz);
        const align = sNorm.dot(up);
        const maxReach = w.restLen + w.radius;
        if (align > 0.25 && wSurf.dist <= maxReach && wSurf.dist > -0.25) {
          w.contact = true;
          const newComp = maxReach - wSurf.dist;
          w.comp = newComp;

          const wVelBody = new Vec3().crossVectors(omega, rBody);
          const wVelWorld = wVelBody.applyQuaternion(quat).add(vel);
          const vNorm = wVelWorld.dot(sNorm);

          let fNorm = Math.max(0, kSpring * newComp - cDamper * vNorm);
          if (newComp > 0.34) {
            const bottomOut = (newComp - 0.34) * mass * 160 - Math.min(0, vNorm) * mass * 18;
            fNorm += Math.max(0, bottomOut);
            const imp = Math.max(0, bottomOut) * dt + (vNorm < -6.5 ? mass * (-vNorm - 6.5) * 0.3 : 0);
            if (imp > maxImpactImpulse) maxImpactImpulse = imp;
            if (imp > mass * 2.2) crashed = true;
          }
          w.load = fNorm;

          const maxFriction = muTire * fNorm;
          const vTang = wVelWorld.clone().addScaledVector(sNorm, -vNorm);
          const wheelFwd = fwd.clone().addScaledVector(sNorm, -fwd.dot(sNorm)).normalize();
          const wheelRight = right.clone().addScaledVector(sNorm, -right.dot(sNorm)).normalize();

          const vLong = vTang.dot(wheelFwd);
          const vLat = vTang.dot(wheelRight);

          let fLong = (driveForceCmd * 0.25) - brakeCmd * Math.max(-maxFriction, Math.min(maxFriction, vLong * mass * 6.5));
          fLong -= vLong * 28;
          const fLat = -vLat * mass * 8.5;

          const fTangMag = Math.hypot(fLong, fLat);
          let scale = 1.0;
          if (fTangMag > maxFriction && fTangMag > 1e-5) scale = maxFriction / fTangMag;
          fLong *= scale;
          const fLatClamped = fLat * scale;

          const totalWheelFWorld = sNorm.clone().multiplyScalar(fNorm)
            .addScaledVector(wheelFwd, fLong)
            .addScaledVector(wheelRight, fLatClamped);

          force.add(totalWheelFWorld);
          const totalWheelFBody = totalWheelFWorld.clone().applyQuaternion(qInv);
          torqueBody.add(new Vec3().crossVectors(rBody, totalWheelFBody));
        } else {
          w.comp = Math.max(0, w.comp - dt * 2.0);
        }
      }
    }

    // Hull collisions
    const hullPts = [
      { id: "ROOF_F", lx: +0.35, ly: +0.58, lz: 0.0 },
      { id: "ROOF_R", lx: -0.65, ly: +0.55, lz: 0.0 },
      { id: "NOSE_L", lx: +2.22, ly: +0.02, lz: -0.75 },
      { id: "NOSE_R", lx: +2.22, ly: +0.02, lz: +0.75 },
      { id: "TAIL_L", lx: -2.22, ly: +0.08, lz: -0.78 },
      { id: "TAIL_R", lx: -2.22, ly: +0.08, lz: +0.78 },
      { id: "SIDE_L", lx: 0.0, ly: +0.10, lz: -0.98 },
      { id: "SIDE_R", lx: 0.0, ly: +0.10, lz: +0.98 }
    ];

    for (const hp of hullPts) {
      const rBody = new Vec3(hp.lx, hp.ly, hp.lz);
      const pWorld = rBody.clone().applyQuaternion(quat).add(pos);
      const hSurf = querySurface(pWorld.x, pWorld.y, pWorld.z);
      if (hSurf && hSurf.dist < 0) {
        const pen = -hSurf.dist;
        const sNorm = new Vec3(hSurf.nx, hSurf.ny, hSurf.nz);
        const pVelBody = new Vec3().crossVectors(omega, rBody);
        const pVelWorld = pVelBody.applyQuaternion(quat).add(vel);
        const vNorm = pVelWorld.dot(sNorm);
        const fHullNorm = Math.max(0, pen * mass * 220 - Math.min(0, vNorm) * mass * 28);
        const impulse = fHullNorm * dt + (vNorm < -1.5 ? mass * (-vNorm) * 0.45 : 0);
        if (impulse > maxImpactImpulse) maxImpactImpulse = impulse;
        if (impulse > mass * 2.0) crashed = true;

        const vTang = pVelWorld.clone().addScaledVector(sNorm, -vNorm);
        const fHullWorld = sNorm.clone().multiplyScalar(fHullNorm).addScaledVector(vTang, -mass * 4.5);
        force.add(fHullWorld);
        const fHullBody = fHullWorld.clone().applyQuaternion(qInv);
        torqueBody.add(new Vec3().crossVectors(rBody, fHullBody));
      }
    }

    if (!crashed) {
      force.z -= pos.z * mass * 15 + vel.z * mass * 6;
      torqueBody.y -= (fwd.z * 8.0 + omega.y * 4.0) * Iyy;
    }

    vel.addScaledVector(force, dt / mass);
    pos.addScaledVector(vel, dt);

    omega.x += (torqueBody.x / Ixx - omega.x * 0.5) * dt;
    omega.y += (torqueBody.y / Iyy - omega.y * 0.8) * dt;
    omega.z += (torqueBody.z / Izz - omega.z * 0.5) * dt;

    const dq = new Quat(omega.x * 0.5 * dt, omega.y * 0.5 * dt, omega.z * 0.5 * dt, 0);
    dq.multiplyQuaternions(quat, dq);
    quat.x += dq.x; quat.y += dq.y; quat.z += dq.z; quat.w += dq.w;
    quat.normalize();
  }

  console.log(cfg.name, {
    finalPhase: phase,
    maxSReached: maxSReached.toFixed(2),
    maxHeight: maxHeight.toFixed(2),
    maxPitchDeg: maxPitchDeg.toFixed(1),
    finalPos: [pos.x.toFixed(2), pos.y.toFixed(2)],
    maxImpactImpulse: Math.round(maxImpactImpulse),
    hoverReached,
    crashed,
    landedCleanly
  });
}

runTest({ name: "DEFAULT", mass: 2000, maxDownforceKg: 4700, entrySpeed: 23.0, totalThrusterForce: 72000, gravity: 9.81 });
runTest({ name: "LOW_DOWNFORCE", mass: 2000, maxDownforceKg: 950, entrySpeed: 23.0, totalThrusterForce: 72000, gravity: 9.81 });
runTest({ name: "THRUSTER_FAILURE", mass: 2000, maxDownforceKg: 4700, entrySpeed: 23.0, totalThrusterForce: 0, gravity: 9.81 });
runTest({ name: "TOO_SLOW", mass: 2000, maxDownforceKg: 4700, entrySpeed: 12.5, totalThrusterForce: 72000, gravity: 9.81 });
'

