          let fLong = (driveForceCmd * 0.25) + Math.max(-maxFriction, Math.min(maxFriction, brakeHoldForce * 0.25));
          fLong -= vLong * 28;
          const fLat = -vLat * mass * 8.5;

          const fTangMag = Math.hypot(fLong, fLat);
