    const hullPts = [
      { id: "ROOF_F", lx: +0.35, ly: +0.58, lz: 0.0 },
      { id: "ROOF_R", lx: -0.65, ly: +0.55, lz: 0.0 },
      { id: "NOSE_L", lx: +2.22, ly: +0.02, lz: -0.75 },
      { id: "NOSE_R", lx: +2.22, ly: +0.02, lz: +0.75 },
      { id: "TAIL_L", lx: -2.22, ly: +0.08, lz: -0.78 },
      { id: "TAIL_R", lx: -2.22, ly: +0.08, lz: +0.78 },
      { id: "SIDE_L", lx: 0.0, ly: +0.10, lz: -0.98 },
      { id: "SIDE_R", lx: 0.0, ly: +0.10, lz: +0.98 }
    ];

    for (const hp of hullPts) {
      const rBody = new Vec3(hp.lx, hp.ly, hp.lz);
      const pWorld = rBody.clone().applyQuaternion(quat).add(pos);
      const hSurf = querySurface(pWorld.x, pWorld.y, pWorld.z, ignoreRamp);
      if (hSurf && hSurf.dist < 0) {
        const pen = -hSurf.dist;
        const sNorm = new Vec3(hSurf.nx, hSurf.ny, hSurf.nz);
        const pVelBody = new Vec3().crossVectors(omega, rBody);
        const pVelWorld = pVelBody.applyQuaternion(quat).add(vel);
        const vNorm = pVelWorld.dot(sNorm);
        const fHullNorm = Math.max(0, pen * mass * 220 - Math.min(0, vNorm) * mass * 28);
        const impulse = fHullNorm * dt + (vNorm < -1.5 ? mass * (-vNorm) * 0.45 : 0);
        if (impulse > maxImpactImpulse) maxImpactImpulse = impulse;
        if (impulse > mass * 2.0) crashed = true;

        const vTang = pVelWorld.clone().addScaledVector(sNorm, -vNorm);
        const fHullWorld = sNorm.clone().multiplyScalar(fHullNorm).addScaledVector(vTang, -mass * 4.5);
        force.add(fHullWorld);
        const fHullBody = fHullWorld.clone().applyQuaternion(qInv);
        torqueBody.add(new Vec3().crossVectors(rBody, fHullBody));
      }
    }

    if (!crashed) {
      force.z -= pos.z * mass * 15 + vel.z * mass * 6;
      torqueBody.y -= (fwd.z * 8.0 + omega.y * 4.0) * Iyy;
    }

    vel.addScaledVector(force, dt / mass);
    pos.addScaledVector(vel, dt);

    omega.x += (torqueBody.x / Ixx - omega.x * 0.5) * dt;
    omega.y += (torqueBody.y / Iyy - omega.y * 0.8) * dt;
    omega.z += (torqueBody.z / Izz - omega.z * 0.5) * dt;

    const dq = new Quat(omega.x * 0.5 * dt, omega.y * 0.5 * dt, omega.z * 0.5 * dt, 0);
    dq.multiplyQuaternions(quat, dq);
    quat.x += dq.x; quat.y += dq.y; quat.z += dq.z; quat.w += dq.w;
    quat.normalize();
  }

  console.log(cfg.name, {
    finalPhase: phase,
    maxSReached: maxSReached.toFixed(2),
    maxHeight: maxHeight.toFixed(2),
    maxPitchDeg: maxPitchDeg.toFixed(1),
    touchdownX: touchdownX !== null ? touchdownX.toFixed(2) : null,
    touchdownT: touchdownT !== null ? touchdownT.toFixed(2) : null,
    finalPos: [pos.x.toFixed(2), pos.y.toFixed(2)],
    maxImpactImpulse: Math.round(maxImpactImpulse),
    hoverReached,
    crashed,
    landedCleanly
  });
}

runScenario({ name: "DEFAULT", mass: 2000, maxDownforceKg: 4700, entrySpeed: 23.0, totalThrusterForce: 72000, gravity: 9.81 });
runScenario({ name: "LOW_DOWNFORCE", mass: 2000, maxDownforceKg: 950, entrySpeed: 23.0, totalThrusterForce: 72000, gravity: 9.81 });
runScenario({ name: "THRUSTER_FAILURE", mass: 2000, maxDownforceKg: 4700, entrySpeed: 23.0, totalThrusterForce: 0, gravity: 9.81 });
