const DEG = Math.PI / 180;
const RAD = 180 / Math.PI;

class Vec3 {
  constructor(x=0, y=0, z=0) { this.x = x; this.y = y; this.z = z; }
  set(x,y,z) { this.x=x; this.y=y; this.z=z; return this; }
  copy(v) { this.x=v.x; this.y=v.y; this.z=v.z; return this; }
  clone() { return new Vec3(this.x, this.y, this.z); }
  add(v) { this.x+=v.x; this.y+=v.y; this.z+=v.z; return this; }
  sub(v) { this.x-=v.x; this.y-=v.y; this.z-=v.z; return this; }
  addScaledVector(v, s) { this.x+=v.x*s; this.y+=v.y*s; this.z+=v.z*s; return this; }
  multiplyScalar(s) { this.x*=s; this.y*=s; this.z*=s; return this; }
  dot(v) { return this.x*v.x + this.y*v.y + this.z*v.z; }
  crossVectors(a, b) {
    const ax=a.x, ay=a.y, az=a.z, bx=b.x, by=b.y, bz=b.z;
    this.x = ay*bz - az*by; this.y = az*bx - ax*bz; this.z = ax*by - ay*bx;
    return this;
  }
  length() { return Math.hypot(this.x, this.y, this.z); }
  normalize() { const l = this.length() || 1; return this.multiplyScalar(1/l); }
  applyQuaternion(q) {
    const x = this.x, y = this.y, z = this.z;
    const qx = q.x, qy = q.y, qz = q.z, qw = q.w;
    const ix = qw * x + qy * z - qz * y;
    const iy = qw * y + qz * x - qx * z;
    const iz = qw * z + qx * y - qy * x;
    const iw = -qx * x - qy * y - qz * z;
    this.x = ix * qw + iw * -qx + iy * -qz - iz * -qy;
    this.y = iy * qw + iw * -qy + iz * -qx - ix * -qz;
    this.z = iz * qw + iw * -qz + ix * -qy - iy * -qx;
    return this;
  }
}

class Quat {
  constructor(x=0, y=0, z=0, w=1) { this.x=x; this.y=y; this.z=z; this.w=w; }
  set(x,y,z,w) { this.x=x; this.y=y; this.z=z; this.w=w; return this; }
  copy(q) { this.x=q.x; this.y=q.y; this.z=q.z; this.w=q.w; return this; }
  clone() { return new Quat(this.x, this.y, this.z, this.w); }
  invert() { this.x=-this.x; this.y=-this.y; this.z=-this.z; return this; }
  normalize() { const l = Math.hypot(this.x, this.y, this.z, this.w) || 1; this.x/=l; this.y/=l; this.z/=l; this.w/=l; return this; }
  multiplyQuaternions(a, b) {
    const qax = a.x, qay = a.y, qaz = a.z, qaw = a.w;
    const qbx = b.x, qby = b.y, qbz = b.z, qbw = b.w;
    this.x = qax * qbw + qaw * qbx + qay * qbz - qaz * qby;
    this.y = qay * qbw + qaw * qby + qaz * qbx - qax * qbz;
    this.z = qaz * qbw + qaw * qbz + qax * qby - qay * qbx;
    this.w = qaw * qbw - qax * qbx - qay * qby - qaz * qbz;
    return this;
  }
}

function createRampGeometry() {
  const targetAngle = 115 * DEG;
  function rawWeight(u) {
    if (u < 0.02) return 0;
    if (u < 0.12) { const t = (u - 0.02) / 0.10; return (0.5 - 0.5 * Math.cos(Math.PI * t)) * 2.75; }
    if (u < 0.44) return 2.75;
    const t = (u - 0.44) / 0.56;
    return 2.75 * (1 - 0.78 * (0.5 - 0.5 * Math.cos(Math.PI * t)));
  }
  const N = 2000;
  let integralW = 0;
  for (let i = 0; i < N; i++) integralW += rawWeight((i + 0.5) / N) / N;
  const kScale = targetAngle / integralW;
  let x = 0, y = 0, theta = 0;
  const rawPts = [{ u: 0, x: 0, y: 0, theta: 0, k: 0 }];
  for (let i = 0; i < N; i++) {
    const u = (i + 0.5) / N, du = 1 / N, k = kScale * rawWeight(u);
    theta += k * du; x += Math.cos(theta) * du; y += Math.sin(theta) * du;
    rawPts.push({ u: (i + 1) / N, x, y, theta, k });
  }
  const L = 20.0 / y;
  const pts = rawPts.map(p => ({ s: p.u * L, x: p.x * L, y: p.y * L, theta: p.theta, k: p.k / L, tx: Math.cos(p.theta), ty: Math.sin(p.theta), nx: -Math.sin(p.theta), ny: Math.cos(p.theta) }));
  return {
    L, width: 6.2, pts,
    sampleAtS(s) {
      const cs = Math.max(0, Math.min(L, s)), idx = Math.min(N - 1, Math.floor((cs / L) * N)), frac = ((cs / L) * N) - idx;
      const a = pts[idx], b = pts[idx + 1], theta = a.theta + (b.theta - a.theta) * frac;
      return { s: cs, x: a.x + (b.x - a.x) * frac, y: a.y + (b.y - a.y) * frac, theta, k: a.k + (b.k - a.k) * frac, tx: Math.cos(theta), ty: Math.sin(theta), nx: -Math.sin(theta), ny: Math.cos(theta) };
    },
    findClosest(px, py) {
      let bestIdx = 0, bestD2 = Infinity;
      for (let i = 0; i <= N; i += 20) { const dx = px - pts[i].x, dy = py - pts[i].y, d2 = dx*dx + dy*dy; if (d2 < bestD2) { bestD2 = d2; bestIdx = i; } }
      for (let i = Math.max(0, bestIdx - 20); i <= Math.min(N, bestIdx + 20); i++) { const dx = px - pts[i].x, dy = py - pts[i].y, d2 = dx*dx + dy*dy; if (d2 < bestD2) { bestD2 = d2; bestIdx = i; } }
      const p = pts[bestIdx], dx = px - p.x, dy = py - p.y, ds = dx * p.tx + dy * p.ty, sRaw = p.s + ds, s = Math.max(0, Math.min(L, sRaw)), exact = this.sampleAtS(s);
      const ex = px - exact.x, ey = py - exact.y, signedDist = ex * exact.nx + ey * exact.ny;
      return { ...exact, sRaw, signedDist };
    }
  };
}
const ramp = createRampGeometry();

function querySurface(px, py, pz, ignoreRamp = false) {
  if (!ignoreRamp && px > -0.5 && Math.abs(pz) <= ramp.width * 0.52) {
    const r = ramp.findClosest(px, py);
    if (r.sRaw >= -0.15 && r.sRaw <= ramp.L + 0.15 && r.signedDist >= -0.35 && r.signedDist < 1.35) {
      if (r.s > 1.2 || r.signedDist < py) {
        return { type: "ramp", dist: r.signedDist, nx: r.nx, ny: r.ny, nz: 0, tx: r.tx, ty: r.ty, tz: 0, s: r.s, sRaw: r.sRaw, theta: r.theta };
      }
    }
  }
  return { type: "ground", dist: py, nx: 0, ny: 1, nz: 0, tx: 1, ty: 0, tz: 0, s: Math.min(0, px), sRaw: px, theta: 0 };
}

function runScenario(cfg) {
  const mass = cfg.mass ?? 2000;
  const maxDownforceKg = cfg.maxDownforceKg ?? 4700;
  const entrySpeed = cfg.entrySpeed ?? 23.0;
  const totalThrusterForce = cfg.totalThrusterForce ?? 72000;
  const gravity = cfg.gravity ?? 9.81;

