  const vel = new Vec3(0, 0, 0);
  const quat = new Quat(0, 0, 0, 1);
  const omega = new Vec3(0, 0, 0);

  const wheels = [
    { id: "FL", lx: +1.42, ly: -0.10, lz: -0.84, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 },
    { id: "FR", lx: +1.42, ly: -0.10, lz: +0.84, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 },
    { id: "RL", lx: -1.40, ly: -0.10, lz: -0.86, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 },
    { id: "RR", lx: -1.40, ly: -0.10, lz: +0.86, restLen: 0.36, radius: 0.34, comp: 0.03, contact: true, load: 0 }
