          const totalWheelFBody = totalWheelFWorld.clone().applyQuaternion(qInv);
          torqueBody.add(new Vec3().crossVectors(rBody, totalWheelFBody));
        } else {
          w.comp = Math.max(0, w.comp - dt * 2.0);
        }
