}

function runScenario(cfg) {
  const mass = cfg.mass ?? 2000;
  const maxDownforceKg = cfg.maxDownforceKg ?? 4700;
  const entrySpeed = cfg.entrySpeed ?? 23.0;
  const totalThrusterForce = cfg.totalThrusterForce ?? 72000;
  const gravity = cfg.gravity ?? 9.81;

  const Ixx = mass * (2.0*2.0 + 1.15*1.15) / 12 * 1.05;
  const Iyy = mass * (4.5*4.5 + 2.0*2.0) / 12 * 0.95;
  const Izz = mass * (4.5*4.5 + 1.15*1.15) / 12 * 0.90;

  const pos = new Vec3(-13.5, 0.48, 0);
  const vel = new Vec3(0, 0, 0);
  const quat = new Quat(0, 0, 0, 1);
  const omega = new Vec3(0, 0, 0);

  const wheels = [
    { id: "FL", lx: +1.42, ly: -0.10, lz: -0.84, restLen: 0.38, radius: 0.34, comp: 0.04, contact: true, load: 0 },
    { id: "FR", lx: +1.42, ly: -0.10, lz: +0.84, restLen: 0.38, radius: 0.34, comp: 0.04, contact: true, load: 0 },
    { id: "RL", lx: -1.40, ly: -0.10, lz: -0.86, restLen: 0.38, radius: 0.34, comp: 0.04, contact: true, load: 0 },
    { id: "RR", lx: -1.40, ly: -0.10, lz: +0.86, restLen: 0.38, radius: 0.34, comp: 0.04, contact: true, load: 0 }
  ];

  const nozzles = [
    { id: "FL_DOWN", lx: +1.35, ly: -0.32, lz: -0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    { id: "FR_DOWN", lx: +1.35, ly: -0.32, lz: +0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    { id: "RL_DOWN", lx: -1.35, ly: -0.32, lz: -0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    { id: "RR_DOWN", lx: -1.35, ly: -0.32, lz: +0.82, fx: 0, fy: 1, fz: 0, thrust: 0 },
    { id: "ROLL_POS_L", lx: 0.0, ly: -0.25, lz: -0.95, fx: 0, fy: +0.92, fz: +0.39, thrust: 0 },
    { id: "ROLL_POS_R", lx: 0.0, ly: +0.25, lz: +0.95, fx: 0, fy: -0.92, fz: -0.39, thrust: 0 },
    { id: "ROLL_NEG_L", lx: 0.0, ly: +0.25, lz: -0.95, fx: 0, fy: -0.92, fz: +0.39, thrust: 0 },
    { id: "ROLL_NEG_R", lx: 0.0, ly: -0.25, lz: +0.95, fx: 0, fy: +0.92, fz: -0.39, thrust: 0 },
    { id: "REAR_L", lx: -2.20, ly: -0.08, lz: -0.36, fx: 1, fy: 0.0, fz: 0, thrust: 0 },
    { id: "REAR_R", lx: -2.20, ly: -0.08, lz: +0.36, fx: 1, fy: 0.0, fz: 0, thrust: 0 }
  ];

  let phase = "WAIT_START", phaseTime = 0, hangTargetS = 26.8, hoverTimer = 0;
  let maxSReached = -14, maxHeight = 0, maxPitchDeg = 0, maxImpactImpulse = 0;
  let crashed = false, landedCleanly = false, hoverReached = false;
  let touchdownX = null, touchdownT = null;
  const dt = 1 / 240;

  for (let step = 0; step < 240 * 14.5; step++) {
    const t = step * dt;
    phaseTime += dt;

    const fwd = new Vec3(1, 0, 0).applyQuaternion(quat);
    const up = new Vec3(0, 1, 0).applyQuaternion(quat);
    const right = new Vec3(0, 0, 1).applyQuaternion(quat);
    const qInv = quat.clone().invert();

    const ignoreRamp = (phase === "AIR_ROLL_AND_BRAKE" || phase === "TOUCHDOWN_DRIVE_OUT" || phase === "FALL_ABORT")
      || (phase === "RELEASE_LIP" && phaseTime > 0.16)
      || (phase === "SLIDE_BACK" && phaseTime > 0.35);

    const surf = querySurface(pos.x, pos.y, pos.z, ignoreRamp);
    const onRamp = surf.type === "ramp";
    const sPos = onRamp ? surf.s : pos.x;
    if (onRamp && sPos > maxSReached) maxSReached = sPos;
    if (pos.y > maxHeight) maxHeight = pos.y;

    let rampPitchDeg = Math.atan2(fwd.y, fwd.x) * RAD;
    if (rampPitchDeg < 0) rampPitchDeg += 360;
    if (onRamp && rampPitchDeg < 150 && rampPitchDeg > maxPitchDeg) maxPitchDeg = rampPitchDeg;

    let driveForceCmd = 0, brakeCmd = 0, holdPositionErr = 0, fanCmd = 0;
    for (const n of nozzles) n.thrust = 0;

    const fwdSpeed = vel.dot(fwd);
    const wheelsInContact = wheels.filter(w => w.contact).length;

    if (phase === "WAIT_START") {
      brakeCmd = 1.0;
      holdPositionErr = -13.5 - pos.x;
      if (t >= 0.65) {
        phase = "CLIMB";
        phaseTime = 0;
      }
    } else if (phase === "CLIMB") {
      fanCmd = sPos > -2.0 ? 1.0 : 0.4;
      const targetS = ramp.L - 1.25;
      const remS = targetS - sPos;

      const speedRatio = Math.pow(Math.max(0.1, entrySpeed / 23.0), 2);
      const stopBrakeProfile = Math.sqrt(Math.max(0, 2 * 13.5 * Math.max(0, remS)));
      const targetV = Math.min(entrySpeed, stopBrakeProfile);
      const vErr = targetV - fwdSpeed;

      if (onRamp && remS <= 0.45 && Math.abs(fwdSpeed) < 1.5 && sPos > ramp.L - 2.6) {
        phase = "HANG";
        phaseTime = 0;
        hangTargetS = sPos;
      } else if (wheelsInContact === 0 && pos.y > 2.5 && vel.y < -1.0) {
        phase = "FALL_ABORT";
        phaseTime = 0;
      } else if (sPos > 4.5 && fwdSpeed < -1.5) {
        phase = "SLIDE_BACK";
        phaseTime = 0;
      } else {
        if (sPos < 5.5) {
          if (vErr > 0) {
            driveForceCmd = Math.min(mass * 22.0 * speedRatio, vErr * mass * 5.8);
            if (sPos < 1.5 && entrySpeed >= 19.0 && vErr > 1.5) {
              nozzles[8].thrust = totalThrusterForce * 0.14;
              nozzles[9].thrust = totalThrusterForce * 0.14;
            }
          }
        } else {
          if (vErr >= 0) {
            driveForceCmd = Math.min(mass * 10.5 * speedRatio, vErr * mass * 4.0 * speedRatio);
          } else {
            brakeCmd = Math.min(1.0, -vErr * 0.45);
          }
        }
      }
    } else if (phase === "HANG") {
      fanCmd = 1.0;
      brakeCmd = 1.0;
      holdPositionErr = hangTargetS - sPos;
      if ((wheelsInContact === 0 && vel.y < -1.5) || fwdSpeed < -2.2) {
        phase = "FALL_ABORT";
        phaseTime = 0;
      } else if (phaseTime >= 2.0) {
        phase = "RELEASE_LIP";
        phaseTime = 0;
      }
    } else if (phase === "RELEASE_LIP") {
      fanCmd = 0.0;
      brakeCmd = 0.0;
      if (phaseTime < 0.15 && wheelsInContact > 0) {
        driveForceCmd = mass * 14.0;
      }
      const pitchToInvHoriz = Math.atan2(fwd.y, -fwd.x);
      const pitchRateCmd = Math.max(-4.5, Math.min(4.5, pitchToInvHoriz * 5.0));
      const pitchTorqueErr = pitchRateCmd - omega.z;
      const sepBoost = (phaseTime < 0.22) ? totalThrusterForce * 0.06 : 0;
      const pDiff = (pitchTorqueErr * Izz * 2.5) / 2.7;
      nozzles[0].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, sepBoost + pDiff));
      nozzles[1].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, sepBoost + pDiff));
      nozzles[2].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, sepBoost - pDiff));
      nozzles[3].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, sepBoost - pDiff));
      if (phaseTime < 0.28) {
        nozzles[8].thrust = totalThrusterForce * 0.08;
        nozzles[9].thrust = totalThrusterForce * 0.08;
      }
      if (phaseTime >= 0.44 && (Math.abs(pitchToInvHoriz) < 12 * DEG || phaseTime >= 0.56)) {
        phase = "AIR_ROLL_AND_BRAKE";
        phaseTime = 0;
      }
    } else if (phase === "AIR_ROLL_AND_BRAKE") {
      fanCmd = 0.0;
      const localUp = new Vec3(0, 1, 0).applyQuaternion(qInv);
      let rollErr = Math.atan2(localUp.z, localUp.y);
      if (rollErr < -0.45) rollErr += 2 * Math.PI;
      const targetRollRate = Math.max(-5.4, Math.min(5.4, rollErr * 4.6));
      const rollCmd = Math.max(-1, Math.min(1, (targetRollRate - omega.x) * 0.65));
      if (rollCmd > 0.01) {
        nozzles[4].thrust = rollCmd * totalThrusterForce * 0.24;
        nozzles[5].thrust = rollCmd * totalThrusterForce * 0.24;
      } else if (rollCmd < -0.01) {
        nozzles[6].thrust = -rollCmd * totalThrusterForce * 0.24;
        nozzles[7].thrust = -rollCmd * totalThrusterForce * 0.24;
      }
      const targetFwdBody = new Vec3(-1, 0, 0).applyQuaternion(qInv);
      const pitchTorqueCmd = (targetFwdBody.y * 10.0 - omega.z * 2.8) * Izz;
      const rollAssistCmd = (up.y > 0.35) ? (rollErr * 5.5 - omega.x * 1.8) * Ixx : 0;

      let baseLiftPerNozzle = 0;
      if (up.y > 0.55 && pos.y < 10.5) {
        if (pos.y < 2.3 && Math.abs(vel.y) < 2.2) {
          hoverReached = true;
        }
        if (hoverReached) hoverTimer += dt;
        const targetVy = (hoverTimer < 0.38)
          ? Math.max(-11.0, Math.min(0.4, (1.35 - pos.y) * 3.6))
          : -1.65;
        const ayCmd = gravity + (targetVy - vel.y) * 7.8;
        const totalLiftNeeded = Math.max(0, (mass * ayCmd) / Math.max(0.55, up.y));
        baseLiftPerNozzle = Math.min(totalThrusterForce * 0.25, totalLiftNeeded * 0.25);
      }
      const dPitch = pitchTorqueCmd / (4 * 1.35);
      const dRoll = rollAssistCmd / (4 * 0.82);
      nozzles[0].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle + dPitch + dRoll));
      nozzles[1].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle + dPitch - dRoll));
      nozzles[2].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle - dPitch + dRoll));
      nozzles[3].thrust = Math.max(0, Math.min(totalThrusterForce * 0.28, baseLiftPerNozzle - dPitch - dRoll));

      if (wheelsInContact >= 3 && pos.y < 0.65 && up.y > 0.88 && Math.abs(vel.y) < 3.0) {
        phase = "TOUCHDOWN_DRIVE_OUT";
        phaseTime = 0;
        touchdownX = pos.x;
        touchdownT = t;
        landedCleanly = !crashed;
      }
    } else if (phase === "TOUCHDOWN_DRIVE_OUT") {
      fanCmd = 0.25;
      if (phaseTime < 0.45) {
        brakeCmd = 0.25;
      } else if (pos.x > -25.0) {
        const targetDriveV = 14.0;
        if (fwdSpeed < targetDriveV) {
          driveForceCmd = mass * 8.5;
        }
      } else {
        brakeCmd = 0.95;
        holdPositionErr = -26.5 - pos.x;
      }
    } else if (phase === "SLIDE_BACK") {
      fanCmd = 0.0;
    }

    const force = new Vec3(0, -mass * gravity, 0);
    const torqueBody = new Vec3(0, 0, 0);
    if (phase === "SLIDE_BACK" && pos.y > 2.5) {
      torqueBody.z -= mass * 14.0;
      torqueBody.x += mass * 6.5;
      force.x -= mass * 3.5;
    }
    if (phase === "FALL_ABORT" && pos.y > 2.5) {
      force.x -= mass * 2.5;
      torqueBody.x += mass * 4.5;
    }

    const speed = vel.length();
    if (speed > 0.01) {
      force.addScaledVector(vel, -0.38 * speed);
    }

    if (surf && fanCmd > 0) {
      const surfN = new Vec3(surf.nx, surf.ny, surf.nz);
      const align = surfN.dot(up);
      if (align > 0.25 && surf.dist < 1.35) {
        const distFactor = 1 / (1 + Math.pow(Math.max(0, surf.dist - 0.34) / 0.48, 2));
        const dfN = fanCmd * (maxDownforceKg * 9.81) * distFactor * align;
        force.addScaledVector(surfN, -dfN);
      }
    }

    for (const n of nozzles) {
      if (n.thrust > 0) {
        const fBody = new Vec3(n.fx * n.thrust, n.fy * n.thrust, n.fz * n.thrust);
        const rBody = new Vec3(n.lx, n.ly, n.lz);
        torqueBody.add(new Vec3().crossVectors(rBody, fBody));
        force.add(fBody.clone().applyQuaternion(quat));
      }
    }

    const kSpring = mass * 56.0;
    const cDamper = mass * 8.5;
    const muTire = 1.20;

    for (const w of wheels) {
      const rBody = new Vec3(w.lx, w.ly, w.lz);
      const wPosWorld = rBody.clone().applyQuaternion(quat).add(pos);
      const wSurf = querySurface(wPosWorld.x, wPosWorld.y, wPosWorld.z, ignoreRamp);
      w.contact = false;
      w.load = 0;
      if (wSurf) {
        const sNorm = new Vec3(wSurf.nx, wSurf.ny, wSurf.nz);
        const align = sNorm.dot(up);
        const maxReach = w.restLen + w.radius;
        if (align > 0.25 && wSurf.dist <= maxReach && wSurf.dist > -0.25) {
          w.contact = true;
          const newComp = maxReach - wSurf.dist;
          w.comp = newComp;

          const wVelBody = new Vec3().crossVectors(omega, rBody);
          const wVelWorld = wVelBody.applyQuaternion(quat).add(vel);
          const vNorm = wVelWorld.dot(sNorm);

          let fNorm = Math.max(0, kSpring * newComp - cDamper * vNorm);
          if (newComp > 0.36) {
            const bottomOut = (newComp - 0.36) * mass * 160 - Math.min(0, vNorm) * mass * 18;
            fNorm += Math.max(0, bottomOut);
            const imp = Math.max(0, bottomOut) * dt + (vNorm < -6.5 ? mass * (-vNorm - 6.5) * 0.3 : 0);
            if (imp > maxImpactImpulse) maxImpactImpulse = imp;
            if (imp > mass * 2.2) crashed = true;
          }
          w.load = fNorm;

          const maxFriction = muTire * fNorm;
          const vTang = wVelWorld.clone().addScaledVector(sNorm, -vNorm);
          const wheelFwd = fwd.clone().addScaledVector(sNorm, -fwd.dot(sNorm)).normalize();
          const wheelRight = right.clone().addScaledVector(sNorm, -right.dot(sNorm)).normalize();

          const vLong = vTang.dot(wheelFwd);
          const vLat = vTang.dot(wheelRight);

          const brakeHoldForce = brakeCmd * (-vLong * mass * 18.0 + holdPositionErr * mass * 35.0);
          let fLong = (driveForceCmd * 0.25) + Math.max(-maxFriction, Math.min(maxFriction, brakeHoldForce * 0.25));
          fLong -= vLong * 28;
          const fLat = -vLat * mass * 8.5;

          const fTangMag = Math.hypot(fLong, fLat);
          let scale = 1.0;
          if (fTangMag > maxFriction && fTangMag > 1e-5) scale = maxFriction / fTangMag;
          fLong *= scale;
          const fLatClamped = fLat * scale;

          const normalWheelFWorld = sNorm.clone().multiplyScalar(fNorm);
          const tangWheelFWorld = wheelFwd.clone().multiplyScalar(fLong).addScaledVector(wheelRight, fLatClamped);
          force.add(normalWheelFWorld).add(tangWheelFWorld);

          const normalWheelFBody = normalWheelFWorld.clone().applyQuaternion(qInv);
          const tangWheelFBody = tangWheelFWorld.clone().applyQuaternion(qInv);
          const rBodyAntiDive = new Vec3(w.lx, -0.02, w.lz);
          torqueBody.add(new Vec3().crossVectors(rBody, normalWheelFBody));
          torqueBody.add(new Vec3().crossVectors(rBodyAntiDive, tangWheelFBody));
        } else {
          w.comp = Math.max(0, w.comp - dt * 2.0);
        }
      }
    }

    const hullPts = [
      { id: "ROOF_F", lx: +0.35, ly: +0.58, lz: 0.0 },
      { id: "ROOF_R", lx: -0.65, ly: +0.55, lz: 0.0 },
      { id: "NOSE_L", lx: +2.10, ly: +0.26, lz: -0.75 },
      { id: "NOSE_R", lx: +2.10, ly: +0.26, lz: +0.75 },
      { id: "TAIL_L", lx: -2.10, ly: +0.28, lz: -0.78 },
      { id: "TAIL_R", lx: -2.10, ly: +0.28, lz: +0.78 },
      { id: "SIDE_L", lx: 0.0, ly: +0.25, lz: -0.98 },
      { id: "SIDE_R", lx: 0.0, ly: +0.25, lz: +0.98 }
    ];

    for (const hp of hullPts) {
      const rBody = new Vec3(hp.lx, hp.ly, hp.lz);
      const pWorld = rBody.clone().applyQuaternion(quat).add(pos);
      const hSurf = querySurface(pWorld.x, pWorld.y, pWorld.z, ignoreRamp);
      if (hSurf && hSurf.dist < 0) {
        const pen = -hSurf.dist;
        const sNorm = new Vec3(hSurf.nx, hSurf.ny, hSurf.nz);
        const pVelBody = new Vec3().crossVectors(omega, rBody);
        const pVelWorld = pVelBody.applyQuaternion(quat).add(vel);
        const vNorm = pVelWorld.dot(sNorm);
        const fHullNorm = Math.max(0, pen * mass * 220 - Math.min(0, vNorm) * mass * 28);
        const impulse = fHullNorm * dt + (vNorm < -1.5 ? mass * (-vNorm) * 0.45 : 0);
        if (impulse > maxImpactImpulse) maxImpactImpulse = impulse;
        if (impulse > mass * 2.0) crashed = true;

        const vTang = pVelWorld.clone().addScaledVector(sNorm, -vNorm);
