      return { ...exact, sRaw, signedDist };
    }
  };
}
const ramp = createRampGeometry();

function querySurface(px, py, pz, ignoreRamp = false) {
  if (!ignoreRamp && px > -0.5 && Math.abs(pz) <= ramp.width * 0.52) {
    const r = ramp.findClosest(px, py);
    if (r.sRaw >= -0.15 && r.sRaw <= ramp.L + 0.15 && r.signedDist >= -0.35 && r.signedDist < 1.35) {
